// Original bilingual teaching material. All numerical cases below are synthetic.
import {writeFileSync} from 'node:fs';
const B=(en,vi)=>({en,vi});
const steps=(title,items,caption)=>({kind:'steps',title,steps:items,caption});
const bars=(title,labels,values,yLabel,caption)=>({kind:'bars',title,xLabel:B('Case','Trường hợp'),yLabel,values:values.map((value,i)=>({label:labels[i],value})),caption});
const S=(title,theory,workedExample,agenda,prompt,hint,answer,deliverable,visual)=>({title,theory,workedExample,agenda:agenda.map(x=>B('60 min — '+x.en,'60 phút — '+x.vi)),exercises:[{id:title.en.toLowerCase().replace(/[^a-z0-9]+/g,'-'),prompt,hint,answer}],deliverable,visual});
const M=(week,title,foundations,sessions)=>({week,title,prerequisites:B('Read a results table, compute a mean and a percentage, and distinguish a prediction from its later outcome. All data required today are provided below.','Biết đọc bảng kết quả, tính trung bình và phần trăm, phân biệt dự báo với kết quả xuất hiện sau đó. Toàn bộ dữ liệu cần dùng được cung cấp bên dưới.'),objectives:[B('Make claims that a reader can trace to the supplied evidence.','Viết kết luận mà người đọc có thể đối chiếu với bằng chứng đã cho.'),B('Explain the reason for each decision and record what remains unknown.','Giải thích lý do của từng quyết định và ghi rõ điều chưa biết.')],foundations,diagram:{kind:'flow',title:B('Five decisions this week','Năm quyết định trong tuần'),labels:sessions.map(s=>s.title),caption:B('Each node is a separate session; this map describes the work, not numerical evidence.','Mỗi nút là một buổi riêng; sơ đồ mô tả công việc, không phải bằng chứng định lượng.')},sessions,references:[]});
const modules=[];
modules.push(M(94,B('Economic interpretation boundaries','Giới hạn diễn giải kinh tế'),B('A forecast is a statement about an outcome. A trading strategy additionally specifies position size, execution time, prices, costs and risk constraints. Forecast accuracy alone does not supply those missing pieces. In this week, one basis point (bp) means 0.01 percentage point of return. All returns are hypothetical one-period, unlevered examples; they are not market observations or promises.','Dự báo là phát biểu về một kết quả. Chiến lược giao dịch còn cần quy mô vị thế, thời điểm thực hiện, giá khớp, chi phí và giới hạn rủi ro. Độ chính xác dự báo không tự cung cấp các phần còn thiếu. Tuần này, một điểm cơ bản (bp) bằng 0,01 điểm phần trăm lợi suất. Các lợi suất đều là ví dụ giả định một kỳ, không dùng đòn bẩy; không phải dữ liệu thị trường hay lời hứa lợi nhuận.'),[
S(B('Accuracy is not a trading return','Độ chính xác không phải lợi suất'),B('Accuracy counts correct signs, giving every observation equal weight. Profit also depends on the size of each move. For a unit long/short position, gross return is position × subsequent asset return. A correct tiny move may be outweighed by one large wrong move. A price forecast also does not prove that an order could have been filled.','Accuracy đếm dấu dự báo đúng, coi mỗi quan sát có trọng số như nhau. Lãi lỗ còn phụ thuộc độ lớn biến động. Với vị thế mua/bán khống một đơn vị, lợi suất gộp bằng vị thế × lợi suất tài sản sau đó. Nhiều lần đúng với biến động nhỏ vẫn có thể thua một lần sai lớn. Dự báo giá cũng không chứng minh lệnh đã khớp được.'),B('Predict up on four periods. Realized returns in bp are [1, 1, 1, −10]. Sign accuracy is 3/4=75%. A hypothetical unit long earns [1,1,1,−10], sum −7 bp before costs. This sum is an additive illustration; compounded return would multiply four gross factors instead. Thus “75% accurate” and “profitable” are different claims.','Dự báo tăng cả bốn kỳ. Lợi suất thực tế giả định theo bp là [1,1,1,−10]. Đúng dấu 3/4=75%. Vị thế mua một đơn vị thu [1,1,1,−10], tổng −7 bp trước chi phí. Đây là phép cộng minh họa; lợi suất kép phải nhân bốn hệ số tăng trưởng. Vì vậy “đúng 75%” và “có lãi” là hai kết luận khác nhau.'),[B('Calculate the four sign matches and gross returns by hand.','Tự tính bốn lần đúng/sai dấu và lợi suất gộp.'),B('Code the two calculations; add a test where all signs are correct.','Viết mã hai phép tính; thêm kiểm thử khi tất cả dấu đều đúng.'),B('Solve the exercise before opening the answer; compare arithmetic and compounded returns.','Giải bài trước khi mở đáp án; so sánh tổng lợi suất với lợi suất kép.'),B('Write 150 words explaining the missing execution evidence and annotate the figure.','Viết 150 từ giải thích bằng chứng khớp lệnh còn thiếu và chú thích hình.')],B('Predict up on five periods with returns [2,2,2,2,−12] bp. Find sign accuracy and additive gross return. Is positive accuracy above 50% sufficient for profit?','Dự báo tăng năm kỳ có lợi suất [2,2,2,2,−12] bp. Tính accuracy và tổng lợi suất gộp. Đúng trên 50% có đủ để có lãi không?'),B('Count positive outcomes, then separately sum their magnitudes.','Đếm kết quả dương rồi cộng riêng độ lớn có dấu.'),B('Four positive outcomes give 4/5=80% accuracy. Gross return is 2+2+2+2−12=−4 bp. The large loss exceeds the four small gains. Therefore this counterexample disproves the proposed implication; it does not say accuracy is always useless.','Bốn kết quả dương cho accuracy 4/5=80%. Tổng gộp là 2+2+2+2−12=−4 bp. Một khoản lỗ lớn vượt bốn khoản lời nhỏ. Phản ví dụ bác bỏ suy luận “accuracy cao thì có lãi”; nó không nói accuracy luôn vô ích.'),B('accuracy-vs-return.md with both calculations and one limited claim.','accuracy-vs-return.md gồm hai phép tính và một kết luận có giới hạn.'),bars(B('The four returns in the example','Bốn lợi suất trong ví dụ'),[1,2,3,4].map(x=>B('Period '+x,'Kỳ '+x)),[1,1,1,-10],B('Gross return (bp)','Lợi suất gộp (bp)'),B('Synthetic unit-long returns. Three positive bars do not outweigh the −10 bp loss.','Lợi suất giả định của vị thế mua một đơn vị. Ba cột dương không bù được khoản lỗ −10 bp.'))),
S(B('Turnover turns fees into drag','Vòng quay vị thế tạo chi phí'),B('Let w_t be the position held for period t. Define one-way turnover as |w_t−w_(t−1)|. If each unit of turnover costs c bp, net period return is w_t r_t−c|w_t−w_(t−1)|. Switching from +1 to −1 has turnover 2, because closing and reopening are both trades. State whether an ending liquidation is included.','Gọi w_t là vị thế giữ trong kỳ t. Vòng quay một chiều là |w_t−w_(t−1)|. Nếu mỗi đơn vị vòng quay tốn c bp, lợi suất ròng kỳ là w_t r_t−c|w_t−w_(t−1)|. Đổi từ +1 sang −1 có vòng quay 2 vì vừa đóng vừa mở vị thế. Phải nêu rõ có tính thanh lý cuối kỳ hay không.'),B('Start w₀=0, then hold [1,−1,0] against returns [4,−3,2] bp. Gross contributions are [4,3,0], total 7. Turnover is [1,2,1], total 4. At c=1 bp, cost is 4 and net is 3 bp. At c=2, net is −1 bp. Break-even cost is 7/4=1.75 bp per unit turnover. The last position is already zero.','Bắt đầu w₀=0, giữ [1,−1,0] khi lợi suất là [4,−3,2] bp. Đóng góp gộp [4,3,0], tổng 7. Vòng quay [1,2,1], tổng 4. Với c=1 bp, phí là 4, ròng 3 bp. Với c=2, ròng −1 bp. Mức phí hòa vốn là 7/4=1,75 bp cho mỗi đơn vị vòng quay. Cuối kỳ vị thế đã bằng 0.'),[B('Recreate the position, return, turnover and fee table.','Lập lại bảng vị thế, lợi suất, vòng quay và phí.'),B('Implement the formula with explicit initial position and test a +1 to −1 switch.','Viết công thức với vị thế đầu kỳ rõ ràng; kiểm thử lần đổi +1 sang −1.'),B('Solve the exercise and draw net return against c from 0 to 4.','Giải bài và vẽ lợi suất ròng theo c từ 0 đến 4.'),B('Document the one-way convention and ending liquidation treatment.','Ghi quy ước một chiều và cách xử lý thanh lý cuối kỳ.')],B('For w₀=0, positions [1,1,0], returns [3,2,−1] bp and c=0.5 bp, compute gross, turnover, net and break-even c.','Với w₀=0, vị thế [1,1,0], lợi suất [3,2,−1] bp và c=0,5 bp, tính gộp, vòng quay, ròng và phí hòa vốn.'),B('Keeping the same position produces zero turnover.','Giữ nguyên vị thế thì vòng quay bằng 0.'),B('Gross=3+2+0=5 bp. Turnover=|1−0|+|1−1|+|0−1|=2. Cost=0.5×2=1 bp, so net=4 bp. Break-even c solves 5−2c=0, giving 2.5 bp. Fees are charged on changes, not every period merely because a position exists.','Gộp=3+2+0=5 bp. Vòng quay=|1−0|+|1−1|+|0−1|=2. Phí=0,5×2=1 bp nên ròng=4 bp. Hòa vốn giải 5−2c=0, được 2,5 bp. Phí tính theo thay đổi vị thế, không tự phát sinh mỗi kỳ chỉ vì đang giữ vị thế.'),B('cost-sensitivity.csv and a tested turnover function.','cost-sensitivity.csv và hàm vòng quay có kiểm thử.'),{kind:'xy',title:B('Net return under stated fees','Lợi suất ròng theo phí đã nêu'),xLabel:B('Cost per unit turnover (bp)','Phí mỗi đơn vị vòng quay (bp)'),yLabel:B('Total net return (bp)','Tổng lợi suất ròng (bp)'),series:[{name:B('7 − 4c','7 − 4c'),mode:'line',points:[[0,7],[1,3],[1.75,0],[2,-1],[3,-5]]}],caption:B('Exact line for gross 7 bp and turnover 4 in the example; fee 1.75 bp crosses zero.','Đường chính xác cho gộp 7 bp và vòng quay 4 trong ví dụ; phí 1,75 bp cắt mức 0.')}),
S(B('Separate exposure from unexplained return','Tách phơi nhiễm khỏi phần chưa giải thích'),B('A simple attribution writes portfolio return r_p=βr_m+α+ε. β is sensitivity to a market factor; α is an intercept under this specified model, not proof of skill. A few observations cannot identify a stable alpha. Today β is given, so residual r_p−βr_m is arithmetic attribution, not an estimated causal effect.','Phân rã đơn giản viết r_p=βr_m+α+ε. β là độ nhạy với nhân tố thị trường; α là hệ số chặn trong mô hình đã chọn, không phải bằng chứng tài năng. Ít quan sát không xác định được alpha ổn định. Hôm nay β được cho sẵn, nên phần dư r_p−βr_m chỉ là phân rã số học, không phải tác động nhân quả được ước lượng.'),B('Let given β=1.5. Market returns are [2,−1,3]% and portfolio returns [3,−1,4]%. Factor contributions are [3,−1.5,4.5]%; residuals are [0,0.5,−0.5]%, mean zero. Portfolio average is 2%; market average is 4/3%, and 1.5×4/3=2%. The positive average is fully accounted for by this given exposure in this sample.','Cho β=1,5. Lợi suất thị trường [2; −1; 3]% và danh mục [3; −1; 4]%. Đóng góp nhân tố [3; −1,5; 4,5]%; phần dư [0; 0,5; −0,5]%, trung bình 0. Danh mục trung bình 2%; thị trường trung bình 4/3%, và 1,5×4/3=2%. Trung bình dương được giải thích hết bởi phơi nhiễm đã cho trong mẫu này.'),[B('Recreate all three attribution rows with units in percentage points.','Tính lại ba hàng phân rã, ghi đơn vị điểm phần trăm.'),B('Write a residual function and test β=0 and β=1.','Viết hàm phần dư, kiểm thử β=0 và β=1.'),B('Solve the exercise and compare mean portfolio and factor returns.','Giải bài, so sánh trung bình danh mục với nhân tố.'),B('Explain why estimating β using the same three rows would add uncertainty.','Giải thích vì sao ước lượng β trên chính ba hàng này làm tăng bất định.')],B('Given β=2, market [1,−2,1]% and portfolio [2,−3,3]%, calculate residuals and their mean. Can this establish repeatable skill?','Cho β=2, thị trường [1; −2; 1]% và danh mục [2; −3; 3]%, tính phần dư và trung bình. Có thể kết luận kỹ năng lặp lại được không?'),B('Subtract twice the market return in each corresponding row.','Trừ hai lần lợi suất thị trường ở từng hàng tương ứng.'),B('Factor contributions=[2,−4,2]%; residuals=[0,1,1] percentage points, mean 2/3 point. This is a positive sample residual under a supplied β. Three observations, an assumed β and omitted factors leave substantial uncertainty; repeatable skill is not established.','Đóng góp nhân tố=[2; −4; 2]%; phần dư=[0; 1; 1] điểm phần trăm, trung bình 2/3 điểm. Đây là phần dư mẫu dương với β cho trước. Ba quan sát, β giả định và nhân tố bị bỏ sót để lại bất định lớn; chưa chứng minh kỹ năng lặp lại được.'),B('exposure-attribution.csv plus a paragraph separating calculation and inference.','exposure-attribution.csv và đoạn phân biệt phép tính với suy luận.'),bars(B('Residual after the given market exposure','Phần dư sau phơi nhiễm thị trường đã cho'),[1,2,3].map(x=>B('Period '+x,'Kỳ '+x)),[0,.5,-.5],B('Residual (percentage points)','Phần dư (điểm phần trăm)'),B('Example residuals r_p−1.5r_m. Their mean is zero; no alpha has been estimated.','Phần dư r_p−1,5r_m của ví dụ. Trung bình bằng 0; chưa ước lượng alpha.'))),
S(B('A delayed trade is a different experiment','Giao dịch trễ là thí nghiệm khác'),B('Information time and execution time must be distinct. If a signal is only available after a period ends, assigning it that same period’s return uses unavailable information. A delay stress test shifts the position and recomputes both return and turnover; it does not simply subtract a constant from the original performance.','Phải tách thời điểm có thông tin với thời điểm thực hiện lệnh. Nếu tín hiệu chỉ có sau khi kỳ kết thúc, gán cho nó lợi suất ngay kỳ đó là dùng thông tin chưa có. Kiểm tra độ trễ phải dịch vị thế rồi tính lại cả lợi suất lẫn vòng quay; không chỉ trừ một hằng số khỏi kết quả cũ.'),B('A signal produced after each close is [1,−1,1]. The three close-to-close returns are [5,−4,3] bp. Illegally pairing same-index signal and return gives 12 bp. With no initial signal, feasible next-period positions are [0,1,−1], giving [0,−4,−3], total −7 bp before costs. There is no fourth return, so the last +1 signal is not scored.','Tín hiệu tạo sau mỗi giá đóng cửa là [1,−1,1]. Ba lợi suất giữa các lần đóng cửa là [5,−4,3] bp. Ghép sai tín hiệu cùng chỉ số với lợi suất cho 12 bp. Khi chưa có tín hiệu ban đầu, vị thế kỳ tiếp theo hợp lệ là [0,1,−1], đóng góp [0,−4,−3], tổng −7 bp trước phí. Không có lợi suất thứ tư nên tín hiệu +1 cuối chưa được chấm.'),[B('Draw the three close times and mark when each signal becomes known.','Vẽ ba mốc đóng cửa và lúc từng tín hiệu được biết.'),B('Implement shift(1) with initial zero; inspect every signal-to-return pairing.','Cài đặt dịch một kỳ với giá trị đầu 0; kiểm tra từng cặp tín hiệu–lợi suất.'),B('Solve the exercise without filling a missing future return.','Giải bài, không tự điền lợi suất tương lai còn thiếu.'),B('Write an assertion that a position uses only signals available before its return interval.','Viết kiểm tra rằng vị thế chỉ dùng tín hiệu có trước khoảng lợi suất của nó.')],B('Signals available after close are [−1,1,1]; returns are [2,3,−2] bp. Compare invalid same-index and feasible one-period-delayed totals.','Tín hiệu có sau đóng cửa [−1,1,1]; lợi suất [2,3,−2] bp. So sánh tổng ghép sai cùng chỉ số với tổng trễ một kỳ hợp lệ.'),B('The valid positions begin with zero, then the first two signals.','Vị thế hợp lệ bắt đầu bằng 0 rồi dùng hai tín hiệu đầu.'),B('Invalid total=(−1)2+1·3+1·(−2)=−1 bp. Valid positions=[0,−1,1], so total=0−3−2=−5 bp. The third signal has no later outcome in this record and must remain unscored. Delay changes the pairing, not the observations themselves.','Tổng sai=(−1)2+1·3+1·(−2)=−1 bp. Vị thế hợp lệ=[0,−1,1] nên tổng=0−3−2=−5 bp. Tín hiệu thứ ba chưa có kết quả sau nó trong bản ghi, phải để chưa chấm. Độ trễ thay đổi cách ghép, không đổi bản thân quan sát.'),B('delay-audit.md with a timestamp table and regression test.','delay-audit.md có bảng thời gian và kiểm thử hồi quy.'),steps(B('The only feasible pairings','Các cặp ghép hợp lệ'),[B('Interval 1: no prior signal → position 0','Khoảng 1: chưa có tín hiệu → vị thế 0'),B('Signal +1 after close 1 → return −4 in interval 2','Tín hiệu +1 sau đóng cửa 1 → lợi suất −4 ở khoảng 2'),B('Signal −1 after close 2 → return +3 in interval 3','Tín hiệu −1 sau đóng cửa 2 → lợi suất +3 ở khoảng 3'),B('Final +1 signal → future return absent','Tín hiệu +1 cuối → chưa có lợi suất tương lai')],B('Each arrow uses a signal before the return interval being scored.','Mỗi mũi tên dùng tín hiệu trước khoảng lợi suất được chấm.'))),
S(B('Write the strongest supported claim','Viết kết luận mạnh nhất có căn cứ'),B('A defensible claim names the task, comparison, sample, metric and limitations. “Lower forecast loss” is justified by forecast evaluation. “Tradable profit” needs executable prices and costs. A boundary document lists what was measured, what was assumed and what evidence is absent. Being specific is stronger than hiding behind “results may vary.”','Kết luận có căn cứ nêu nhiệm vụ, đối chứng, mẫu, thước đo và giới hạn. “Sai số dự báo thấp hơn” cần đánh giá dự báo. “Lợi nhuận giao dịch khả thi” cần giá thực hiện được và chi phí. Tài liệu giới hạn tách thứ đã đo, thứ giả định và bằng chứng còn thiếu. Cụ thể tốt hơn câu mơ hồ “kết quả có thể thay đổi”.'),B('Provided record: 200 chronological forecasts; mean squared error A=0.90, baseline=1.00; no confidence interval; no bid/ask or fill logs. A defensible sentence is: “On these 200 held-out forecasts, A had 10% lower sample MSE than the baseline; uncertainty and executable trading returns were not evaluated.” Relative reduction=(1−0.90)/1=10%. Do not call this a 10% investment return.','Bản ghi cho trước: 200 dự báo theo thời gian; MSE A=0,90, đối chứng=1,00; chưa có khoảng tin cậy; không có bid/ask hay nhật ký khớp lệnh. Câu phù hợp: “Trên 200 dự báo giữ lại này, A có MSE mẫu thấp hơn đối chứng 10%; chưa đánh giá bất định và lợi suất giao dịch thực hiện được.” Mức giảm tương đối=(1−0,90)/1=10%. Không gọi đây là lợi suất đầu tư 10%.'),[B('Underline each part of the claim that maps to a supplied field.','Gạch chân từng phần kết luận nối với trường dữ liệu đã cho.'),B('Make a three-column table: measured, assumed, absent.','Lập bảng ba cột: đã đo, giả định, còn thiếu.'),B('Solve the rewrite exercise and compare its scope with the answer.','Làm bài sửa câu kết luận rồi đối chiếu phạm vi với đáp án.'),B('Combine this week’s costs, exposure and delay findings in claims-boundary.md.','Gộp kết quả phí, phơi nhiễm và độ trễ của tuần vào claims-boundary.md.')],B('Record: 50 held-out forecasts, MAE 4 versus baseline 5, no execution data and no uncertainty estimate. Rewrite “Our strategy earns 20% more and will work in all markets.”','Bản ghi: 50 dự báo giữ lại, MAE 4 so với đối chứng 5, không có dữ liệu khớp lệnh hay ước lượng bất định. Sửa câu “Chiến lược lời hơn 20% và hiệu quả ở mọi thị trường”.'),B('Replace profit with the actual error metric and restrict the population.','Thay lợi nhuận bằng đúng thước đo sai số, giới hạn phạm vi mẫu.'),B('“On 50 held-out forecasts, the model’s sample MAE was 4 versus 5 for the baseline, a 20% relative reduction. Uncertainty, execution costs and performance in other settings remain untested.” The percentage is (5−4)/5, not a return. The universal and profit claims have no evidence in this record.','“Trên 50 dự báo giữ lại, MAE mẫu của mô hình là 4 so với 5 của đối chứng, giảm tương đối 20%. Chưa kiểm tra bất định, phí thực hiện hay kết quả ở bối cảnh khác.” Tỷ lệ là (5−4)/5, không phải lợi suất. Bản ghi không có bằng chứng cho kết luận lợi nhuận hoặc mọi thị trường.'),B('claims-boundary.md with a claim-to-evidence table.','claims-boundary.md có bảng nối kết luận với bằng chứng.'),steps(B('Evidence limits the sentence','Bằng chứng giới hạn câu kết luận'),[B('Observed: MSE 0.90 vs 1.00 on 200 forecasts','Đã quan sát: MSE 0,90 so với 1,00 trên 200 dự báo'),B('Calculated: 10% relative sample error reduction','Tính được: giảm 10% sai số mẫu tương đối'),B('Absent: uncertainty, executable quotes and fills','Còn thiếu: bất định, báo giá khả thi và lệnh khớp'),B('Conclusion: forecast result only within this sample','Kết luận: kết quả dự báo trong phạm vi mẫu này')],B('A reasoning diagram, not a graph of investment performance.','Sơ đồ lập luận, không phải đồ thị lợi nhuận đầu tư.')))
]));

modules.push(M(95,B('Synthesize results without hiding conflicts','Tổng hợp kết quả và giữ lại mâu thuẫn'),B('A research result is a collection of comparisons, not the single most attractive number. Primary analyses answer the question fixed before evaluation. Exploratory analyses suggest new questions and must retain that label. Aggregation changes the weighting of evidence: a pooled average weights observations, whereas an average across datasets may weight each dataset equally. Neither weighting is automatically the right scientific target.','Kết quả nghiên cứu là tập hợp các phép so sánh, không phải con số đẹp nhất. Phân tích chính trả lời câu hỏi được chốt trước đánh giá. Phân tích khám phá gợi ý câu hỏi mới và phải giữ nhãn đó. Tổng hợp làm thay đổi trọng số bằng chứng: trung bình gộp đặt trọng số theo số quan sát, còn trung bình giữa bộ dữ liệu có thể coi mỗi bộ ngang nhau. Không cách nào tự động là mục tiêu khoa học đúng.'),[
S(B('Primary and exploratory evidence','Bằng chứng chính và khám phá'),B('A primary metric is chosen before looking at evaluation outcomes. Selecting the smallest error among many metrics after seeing results favors chance successes. An exploratory finding can still be valuable, but it needs fresh validation rather than being retroactively called the original hypothesis.','Thước đo chính được chọn trước khi xem kết quả đánh giá. Chọn sai số đẹp nhất trong nhiều thước đo sau khi xem sẽ ưu ái thành công do ngẫu nhiên. Kết quả khám phá vẫn có ích, nhưng cần kiểm chứng mới thay vì đổi tên thành giả thuyết ban đầu.'),B('Protocol P1 names MAE as primary. Results: baseline MAE=2.0, model MAE=2.2; baseline MSE=9, model MSE=8. The primary comparison worsens by (2.2−2)/2=10%. MSE improves 11.1% but was not prespecified. Report both with their roles; the MSE result cannot rescue the failed primary claim.','Giao thức P1 chọn MAE làm chính. Kết quả: MAE đối chứng=2,0, mô hình=2,2; MSE đối chứng=9, mô hình=8. So sánh chính xấu đi (2,2−2)/2=10%. MSE tốt hơn 11,1% nhưng chưa được định trước. Báo cả hai đúng vai trò; MSE không biến kết luận chính thất bại thành thành công.'),[B('Recalculate both relative changes and name their denominators.','Tính lại hai mức thay đổi, ghi rõ mẫu số.'),B('Create a results table with a prespecified/exploratory column.','Lập bảng kết quả có cột định trước/khám phá.'),B('Solve the exercise and write one sentence for each metric.','Giải bài và viết một câu cho mỗi thước đo.'),B('Draft a protocol deviation log for the newly inspected MSE.','Soạn nhật ký lệch giao thức cho MSE mới xem thêm.')],B('Primary RMSE changes from 3 to 3.3, exploratory MAE from 2 to 1.8. Which result answers the planned question? What should be reported?','RMSE chính đổi từ 3 lên 3,3, MAE khám phá từ 2 xuống 1,8. Kết quả nào trả lời câu hỏi định trước? Phải báo điều gì?'),B('Metric role comes from the protocol, not which sign is favorable.','Vai trò thước đo do giao thức quyết định, không do dấu có lợi.'),B('Primary RMSE worsens 10%; that answers the planned comparison. Exploratory MAE improves 10%. Report both, identify the conflict and propose a fresh test of the MAE hypothesis. Changing the primary label after observing results conceals selection.','RMSE chính xấu hơn 10%, trả lời so sánh định trước. MAE khám phá tốt hơn 10%. Báo cả hai, nêu mâu thuẫn và đề xuất kiểm tra MAE trên mẫu mới. Đổi nhãn chính sau khi xem che giấu việc lựa chọn.'),B('primary-exploratory.csv and a two-sentence conclusion.','primary-exploratory.csv và kết luận hai câu.'),steps(B('Protocol before results','Giao thức trước kết quả'),[B('P1: MAE is primary','P1: MAE là chính'),B('MAE: 2.0 → 2.2, worse','MAE: 2,0 → 2,2, xấu hơn'),B('MSE: 9 → 8, exploratory improvement','MSE: 9 → 8, cải thiện khám phá')],B('MAE and MSE have different units, so they are not placed on a shared numeric axis.','MAE và MSE khác đơn vị, nên không đặt chung một trục số.'))),
S(B('Paired differences retain the comparison','Chênh lệch ghép cặp giữ đúng so sánh'),B('Use the same evaluation rows for both methods. Define d_t=loss_A,t−loss_B,t; negative favors A. The mean difference is a sample summary. Its uncertainty depends on sample size and dependence, so four rows cannot justify a broad significance claim. Unpaired means can compare different environments instead of methods.','Dùng cùng hàng đánh giá cho hai phương pháp. Đặt d_t=loss_A,t−loss_B,t; âm có lợi cho A. Trung bình chênh lệch là tóm tắt mẫu. Bất định phụ thuộc cỡ mẫu và phụ thuộc thời gian, nên bốn hàng không đủ cho kết luận ý nghĩa rộng. Trung bình không ghép cặp có thể đang so môi trường khác nhau thay vì phương pháp.'),B('A losses=[1,4,2,5], B=[2,3,3,6]. Paired differences=[−1,1,−1,−1], mean −0.5. A wins 3 of 4 rows, but loses row 2. Both mean loss and the full difference sequence belong in the result; a win count discards magnitude.','Sai số A=[1,4,2,5], B=[2,3,3,6]. Chênh lệch ghép=[−1,1,−1,−1], trung bình −0,5. A thắng 3/4 hàng nhưng thua hàng 2. Cần báo trung bình và cả chuỗi chênh lệch; số lần thắng bỏ qua độ lớn.'),[B('Check the paired differences row by row.','Kiểm tra chênh lệch từng hàng.'),B('Implement a join by row ID and reject missing partners.','Ghép theo ID hàng và từ chối hàng thiếu đối tác.'),B('Solve the exercise; contrast win count with mean difference.','Giải bài, so số lần thắng với trung bình chênh lệch.'),B('Write why an IID standard error may fail for serial losses.','Giải thích vì sao sai số chuẩn IID có thể sai với chuỗi sai số.')],B('A=[1,1,10], B=[2,2,2]. Compute win count and mean paired difference. Which method has smaller mean loss?','A=[1,1,10], B=[2,2,2]. Tính số lần thắng và trung bình chênh lệch. Phương pháp nào có sai số trung bình thấp hơn?'),B('The last difference is much larger than the first two.','Chênh lệch cuối lớn hơn nhiều hai chênh lệch đầu.'),B('Differences=[−1,−1,8], mean=6/3=2. A wins 2/3 rows yet mean loss A=4 exceeds B=2. B wins the mean-loss comparison. The count and mean answer different questions; neither should be silently substituted for the other.','Chênh lệch=[−1,−1,8], trung bình=6/3=2. A thắng 2/3 hàng nhưng sai số trung bình A=4 lớn hơn B=2. B thắng theo sai số trung bình. Số lần thắng và trung bình trả lời hai câu hỏi khác nhau, không được âm thầm thay thế.'),B('paired-results.csv with a checked row-ID join.','paired-results.csv có ghép ID đã kiểm tra.'),bars(B('Example paired loss differences','Chênh lệch sai số ghép cặp trong ví dụ'),[1,2,3,4].map(x=>B('Row '+x,'Hàng '+x)),[-1,1,-1,-1],B('Loss A − loss B','Sai số A − sai số B'),B('Same four rows for both models; negative bars favor A.','Cùng bốn hàng cho hai mô hình; cột âm có lợi cho A.'))),
S(B('Explain weighting before pooling','Giải thích trọng số trước khi gộp'),B('A pooled mean weights each observation equally. An unweighted mean of group means gives a small group the same influence as a large one. Choose the target first: the average evaluated row or the average environment? Report group counts so another reader can reconstruct your choice.','Trung bình gộp coi mỗi quan sát ngang nhau. Trung bình không trọng số của trung bình nhóm cho nhóm nhỏ ảnh hưởng bằng nhóm lớn. Chọn mục tiêu trước: hàng đánh giá trung bình hay môi trường trung bình? Báo số lượng từng nhóm để người khác dựng lại lựa chọn.'),B('Environment X has n=90 and mean difference −1; Y has n=10 and mean difference +5. Pooled difference=(90·(−1)+10·5)/100=−0.4, favoring A. Equal-environment mean=(−1+5)/2=2, favoring B. This is a change of estimand, not an arithmetic contradiction.','Môi trường X có n=90, chênh lệch trung bình −1; Y có n=10, trung bình +5. Gộp=(90·(−1)+10·5)/100=−0,4, lợi cho A. Coi môi trường ngang nhau=(−1+5)/2=2, lợi cho B. Đây là đổi đại lượng mục tiêu, không phải mâu thuẫn số học.'),[B('Derive the weighted mean from total loss differences.','Suy ra trung bình có trọng số từ tổng chênh lệch.'),B('Make a two-row table preserving n and mean for X and Y.','Lập bảng hai hàng giữ n và trung bình của X, Y.'),B('Solve the exercise and draw both group means.','Giải bài và vẽ hai trung bình nhóm.'),B('Write which target fits equal importance across environments and why.','Viết mục tiêu phù hợp khi các môi trường quan trọng ngang nhau, giải thích lý do.')],B('Group means are −2 and +4 with counts 20 and 80. Compute pooled and equal-group means.','Hai trung bình nhóm là −2 và +4 với số lượng 20 và 80. Tính trung bình gộp và coi nhóm ngang nhau.'),B('Weights are 0.2 and 0.8 for pooling, 0.5 and 0.5 for equal groups.','Trọng số gộp 0,2 và 0,8; ngang nhóm 0,5 và 0,5.'),B('Pooled=0.2(−2)+0.8(4)=2.8. Equal-group=(−2+4)/2=1. Both favor B under d=A−B, with different effect sizes because they target different populations. The count of 80 gives group two more influence only in the pooled target.','Gộp=0,2(−2)+0,8(4)=2,8. Ngang nhóm=(−2+4)/2=1. Cả hai lợi cho B khi d=A−B, nhưng độ lớn khác vì mục tiêu quần thể khác. Nhóm 80 quan sát chỉ có ảnh hưởng nhiều hơn trong mục tiêu gộp.'),B('aggregation-policy.md stating the estimand and weights.','aggregation-policy.md nêu đại lượng mục tiêu và trọng số.'),bars(B('Same evidence, different summaries','Cùng bằng chứng, khác cách tóm tắt'),[B('X (n=90)','X (n=90)'),B('Y (n=10)','Y (n=10)'),B('Pooled','Gộp'),B('Equal groups','Ngang nhóm')],[-1,5,-.4,2],B('Mean loss difference A − B','Chênh lệch sai số trung bình A − B'),B('All bars use the same loss units; the last two apply the stated weights.','Các cột cùng đơn vị sai số; hai cột cuối áp dụng trọng số đã nêu.'))),
S(B('Trace every figure to a result record','Truy từng hình về bản ghi kết quả'),B('A result identifier links configuration, data version, code version and output. A filename such as final.csv is not enough because it can be overwritten. A manifest is a small table recording these links. A figure should cite the exact result IDs it uses; a mismatch is a reproducibility defect even when the picture looks plausible.','ID kết quả nối cấu hình, phiên bản dữ liệu, phiên bản mã và đầu ra. Tên final.csv chưa đủ vì có thể bị ghi đè. Manifest là bảng nhỏ lưu các mối nối này. Hình cần dẫn đúng ID kết quả đã dùng; sai nối là lỗi tái lập dù hình trông hợp lý.'),B('Provided ledger: R1=(data D1, code C1, seed 7, MAE 2.0); R2=(D1,C2,7,1.8). Figure F1 claims to show C2 but its source column says R1. The numeric value 2.0 belongs to C1. Fix F1 to use R2 and 1.8, or change its label to C1; never simply relabel 2.0 as C2.','Sổ cho trước: R1=(dữ liệu D1, mã C1, seed 7, MAE 2,0); R2=(D1,C2,7,1,8). Hình F1 ghi C2 nhưng cột nguồn là R1. Số 2,0 thuộc C1. Sửa F1 dùng R2 và 1,8 hoặc đổi nhãn thành C1; không đổi nhãn 2,0 thành C2 mà giữ dữ liệu cũ.'),[B('Represent R1, R2 and F1 as JSON records.','Biểu diễn R1, R2, F1 thành JSON.'),B('Write a validator comparing the figure’s declared code with its source record.','Viết kiểm tra mã khai báo của hình khớp bản ghi nguồn.'),B('Solve the exercise and retain the incorrect figure in an audit folder.','Giải bài, giữ hình sai trong thư mục kiểm toán.'),B('Produce results-index.md listing configuration, inputs and outputs for each result.','Tạo results-index.md ghi cấu hình, đầu vào, đầu ra từng kết quả.')],B('R3 uses D2,C2 and reports 1.6. A table compares R1 and R3 as a “code-only improvement.” Explain the confounding and give a valid next experiment.','R3 dùng D2,C2 và báo 1,6. Bảng so R1 với R3 gọi là “cải thiện chỉ do mã”. Giải thích nhiễu và đề xuất thí nghiệm hợp lệ.'),B('Both data and code changed between R1 and R3.','Cả dữ liệu lẫn mã đổi giữa R1 và R3.'),B('R1→R3 changes D1→D2 and C1→C2, so the 0.4 reduction cannot be assigned to code alone. Run C1 and C2 on the same frozen D2 with identical evaluation rules, or use the existing R1/R2 comparison on D1. A controlled comparison holds the other inputs fixed.','R1→R3 đổi D1→D2 và C1→C2 nên không quy mức giảm 0,4 riêng cho mã. Chạy C1, C2 trên cùng D2 đóng băng với quy tắc đánh giá giống nhau, hoặc dùng R1/R2 trên D1. So sánh có kiểm soát giữ cố định các đầu vào khác.'),B('results-index.md and one manifest consistency test.','results-index.md và một kiểm thử tính nhất quán manifest.'),steps(B('Correct provenance for F1','Nguồn đúng cho F1'),[B('D1 + C2 + seed 7','D1 + C2 + seed 7'),B('Result R2: MAE 1.8','Kết quả R2: MAE 1,8'),B('Figure F1: source R2, label C2','Hình F1: nguồn R2, nhãn C2')],B('Arrows mean “generated from”; identifiers are synthetic teaching labels.','Mũi tên nghĩa là “được tạo từ”; ID là nhãn giả định phục vụ học.'))),
S(B('Write a balanced synthesis','Viết tổng hợp cân bằng'),B('A synthesis explains what evidence jointly supports and challenges a hypothesis. A negative result may narrow the domain where a method is useful. Avoid treating “no clear evidence” as proof of exact equality. Distinguish measured outcomes from explanations that remain hypotheses.','Tổng hợp giải thích bằng chứng nào ủng hộ và thách thức giả thuyết. Kết quả âm có thể thu hẹp miền phương pháp hữu ích. Đừng biến “chưa có bằng chứng rõ” thành chứng minh bằng nhau tuyệt đối. Tách kết quả đã đo khỏi cách giải thích còn là giả thuyết.'),B('Supplied summaries: stable regime difference −0.3; shift regime +0.4; pooled −0.05 with interval [−0.2,0.1], where d=A−B. A supported synthesis says A improves sample loss in the stable regime but worsens after shifts; pooled uncertainty spans zero. “A universally wins” is contradicted. “Adaptation delay explains the loss” is only a hypothesis until delay is measured.','Tóm tắt cho trước: chế độ ổn định chênh lệch −0,3; chế độ đổi +0,4; gộp −0,05 với khoảng [−0,2;0,1], d=A−B. Tổng hợp phù hợp: A giảm sai số mẫu khi ổn định nhưng tăng sau thay đổi; khoảng bất định gộp chứa 0. “A luôn thắng” bị bác bỏ. “Độ trễ thích nghi gây thua” chỉ là giả thuyết cho tới khi đo độ trễ.'),[B('Separate each supplied statement into observation or explanation.','Phân loại từng phát biểu thành quan sát hay giải thích.'),B('Write one supporting and one challenging paragraph with exact numbers.','Viết một đoạn ủng hộ và một đoạn thách thức có số cụ thể.'),B('Solve the exercise without converting an interval into a probability about the hypothesis.','Giải bài, không đổi khoảng tin cậy thành xác suất của giả thuyết.'),B('Assemble results-synthesis.md with primary, subgroup and negative findings.','Tạo results-synthesis.md gồm kết quả chính, nhóm con và kết quả âm.')],B('A pooled difference is −0.1 with interval [−0.4,0.2]. Rewrite “The methods are identical” and propose one informative next measurement.','Chênh lệch gộp −0,1 với khoảng [−0,4;0,2]. Sửa câu “Hai phương pháp giống hệt” và đề xuất một phép đo tiếp theo hữu ích.'),B('The interval includes both improvements and deteriorations of practical size.','Khoảng chứa cả cải thiện và suy giảm có độ lớn đáng kể.'),B('“This estimate is imprecise: the interval includes zero and effects in both directions, so exact equality is not established.” A useful next measurement is prespecified regime-specific loss with enough independent evaluation blocks, which can reveal whether opposite regime effects cancel. More data alone does not repair a biased evaluation.','“Ước lượng còn thiếu chính xác: khoảng chứa 0 và tác động hai hướng, nên chưa chứng minh bằng nhau tuyệt đối.” Có thể đo sai số theo chế độ được định trước trên đủ khối đánh giá độc lập để xem hai hướng có triệt tiêu nhau không. Thêm dữ liệu tự nó không sửa đánh giá bị lệch.'),B('results-synthesis.md including the strongest negative finding.','results-synthesis.md có kết quả âm mạnh nhất.'),bars(B('The two supplied regime effects','Hai hiệu ứng chế độ đã cho'),[B('Stable','Ổn định'),B('Shift','Thay đổi')],[-.3,.4],B('Mean loss difference A − B','Chênh lệch sai số trung bình A − B'),B('Point estimates only; no subgroup uncertainty was supplied, so none is invented.','Chỉ là ước lượng điểm; đề không cho bất định nhóm con nên không tự vẽ thêm.')))
]));

modules.push(M(96,B('Build an auditable manuscript','Viết bản thảo có thể kiểm chứng'),B('A manuscript connects a question to evidence through an explicit method. Its abstract is a compressed argument, not an advertisement. Methods let a reader reconstruct the experiment; results report what happened; discussion explains what it may mean. A quantitative sentence should have an identifiable source, unit and population. This week uses a small fictional study so every editing decision can be practiced without opening another document.','Bản thảo nối câu hỏi với bằng chứng qua phương pháp rõ ràng. Tóm tắt là lập luận nén, không phải quảng cáo. Phương pháp giúp dựng lại thí nghiệm; kết quả báo chuyện đã xảy ra; thảo luận giải thích ý nghĩa có thể có. Mỗi câu định lượng cần nguồn, đơn vị và quần thể xác định. Tuần này dùng nghiên cứu giả định nhỏ, nên mọi quyết định biên tập đều thực hành được ngay trong bài.'),[
S(B('Question, estimand, contribution','Câu hỏi, đại lượng mục tiêu, đóng góp'),B('A research question must identify what varies and what is measured. An estimand is the precise quantity you want to learn, such as expected paired loss difference after a shift. A contribution states what your work adds: a new method, a controlled comparison, a counterexample or a reproducible negative result. New code alone is not automatically a new scientific method.','Câu hỏi nghiên cứu cần chỉ rõ thứ thay đổi và thứ được đo. Đại lượng mục tiêu là thứ chính xác muốn biết, chẳng hạn kỳ vọng chênh lệch sai số ghép cặp sau thay đổi. Đóng góp nói công trình thêm gì: phương pháp mới, so sánh có kiểm soát, phản ví dụ hoặc kết quả âm tái lập được. Mã mới không tự động là phương pháp khoa học mới.'),B('Fictional study compares fixed step size η=0.1 with η=0.5 on 20 generated mean-shift streams. Question: does the faster update reduce average squared forecast loss in the first 10 post-shift steps? Estimand: mean over streams of that 10-step paired loss difference. Contribution: a controlled sensitivity study, not a universal forecasting theorem.','Nghiên cứu giả định so bước η=0,1 với η=0,5 trên 20 chuỗi sinh có đổi trung bình. Câu hỏi: cập nhật nhanh hơn có giảm sai số bình phương dự báo trong 10 bước đầu sau đổi không? Đại lượng mục tiêu: trung bình giữa các chuỗi của chênh lệch ghép cặp trong 10 bước đó. Đóng góp: nghiên cứu độ nhạy có kiểm soát, không phải định lý dự báo phổ quát.'),[B('Write the population, intervention, comparator and outcome as four fields.','Viết bốn trường: quần thể, can thiệp, đối chứng, kết quả.'),B('Express the estimand as a mean over 20 stream-level differences.','Viết đại lượng mục tiêu dưới dạng trung bình 20 chênh lệch cấp chuỗi.'),B('Solve the exercise and remove any unsupported novelty claim.','Giải bài, bỏ tuyên bố mới lạ không có căn cứ.'),B('Draft a 200-word introduction ending in one precise research question.','Soạn mở đầu 200 từ kết bằng một câu hỏi nghiên cứu chính xác.')],B('A study reimplements an existing online mean update and evaluates two step sizes on synthetic streams. Rewrite “We invent a new intelligent forecasting algorithm.”','Nghiên cứu cài lại cập nhật trung bình trực tuyến có sẵn và đánh giá hai bước học trên chuỗi giả lập. Sửa câu “Chúng tôi phát minh thuật toán dự báo thông minh mới”.'),B('Describe the controlled comparison that was actually performed.','Mô tả đúng phép so sánh có kiểm soát đã làm.'),B('“We provide a reproducible comparison of two step sizes for an existing online mean update under specified synthetic shifts.” This credits the existing method and locates the contribution in evaluation. Claiming algorithmic invention would require a genuinely new method and a documented comparison with prior work.','“Chúng tôi cung cấp so sánh tái lập được giữa hai bước học của cập nhật trung bình trực tuyến có sẵn dưới các thay đổi giả lập xác định.” Câu này ghi nhận phương pháp có trước và đặt đóng góp ở đánh giá. Tuyên bố phát minh thuật toán cần phương pháp thật sự mới và đối chiếu công trình trước.'),B('introduction.md with a bounded contribution statement.','introduction.md có phát biểu đóng góp đúng phạm vi.'),steps(B('Question becomes a measurable target','Câu hỏi thành mục tiêu đo được'),[B('Compare η=0.5 against η=0.1','So η=0,5 với η=0,1'),B('Score first 10 post-shift forecasts per stream','Chấm 10 dự báo đầu sau đổi của mỗi chuỗi'),B('Average 20 paired stream differences','Lấy trung bình 20 chênh lệch ghép cấp chuỗi')],B('The stream, not each correlated time step, is the aggregation unit here.','Đơn vị tổng hợp ở đây là chuỗi, không phải từng bước thời gian có tương quan.'))),
S(B('Methods as executable instructions','Phương pháp như hướng dẫn thực thi'),B('A method description must fix data generation, information order, initialization, update rule and scoring. “We used online learning” leaves many incompatible implementations. Pseudocode should make clear whether a target is scored before or after updating. The wrong order can create a deceptively small loss.','Mô tả phương pháp phải chốt cách sinh dữ liệu, thứ tự thông tin, khởi tạo, quy tắc cập nhật và cách chấm. “Dùng học trực tuyến” còn cho phép nhiều cài đặt khác nhau. Mã giả cần rõ chấm mục tiêu trước hay sau cập nhật. Sai thứ tự có thể tạo sai số nhỏ giả tạo.'),B('Let θ₀=0, η=0.5, targets [2,2]. At t=1 predict 0, record loss 4, then update θ₁=1. At t=2 predict 1, record loss 1, then update θ₂=1.5. Mean loss=2.5. Scoring after updating would report losses 1 and 0.25, mean 0.625, but these are fitted errors using the target being scored.','Cho θ₀=0, η=0,5, mục tiêu [2,2]. Tại t=1 dự báo 0, ghi sai số 4 rồi cập nhật θ₁=1. Tại t=2 dự báo 1, ghi sai số 1 rồi cập nhật θ₂=1,5. Sai số trung bình=2,5. Chấm sau cập nhật sẽ báo 1 và 0,25, trung bình 0,625, nhưng đó là sai số khớp đã dùng chính mục tiêu đang chấm.'),[B('Reproduce the four values: prediction, target, loss and updated state.','Dựng lại bốn giá trị: dự báo, mục tiêu, sai số, trạng thái mới.'),B('Write six-line pseudocode with an immutable forecast log.','Viết mã giả sáu dòng với nhật ký dự báo không sửa lại.'),B('Solve the exercise and test a deliberately wrong update-first implementation.','Giải bài, kiểm thử cài đặt cố ý sai là cập nhật trước.'),B('Write methods.md including initialization, units and scoring order.','Viết methods.md có khởi tạo, đơn vị và thứ tự chấm.')],B('Use θ₀=1, η=0.5 and targets [3,1]. Compute forecast-time losses and the final state.','Dùng θ₀=1, η=0,5, mục tiêu [3,1]. Tính sai số lúc dự báo và trạng thái cuối.'),B('Each prediction is the state before the current target update.','Mỗi dự báo là trạng thái trước khi cập nhật bằng mục tiêu hiện tại.'),B('Predict 1 for target 3: loss 4, update to 2. Predict 2 for target 1: loss 1, update to 1.5. Mean loss=(4+1)/2=2.5. Final state 1.5 is available only after both outcomes, so it cannot replace either historical forecast.','Dự báo 1 cho mục tiêu 3: sai số 4, cập nhật thành 2. Dự báo 2 cho mục tiêu 1: sai số 1, cập nhật thành 1,5. Trung bình=(4+1)/2=2,5. Trạng thái cuối 1,5 chỉ có sau cả hai kết quả, không được thay dự báo lịch sử.'),B('methods.md and an order-of-operations test.','methods.md và kiểm thử thứ tự thao tác.'),steps(B('Correct online loop','Vòng lặp trực tuyến đúng'),[B('State 0 → predict 0','Trạng thái 0 → dự báo 0'),B('Reveal 2 → loss 4 → update state 1','Thấy 2 → sai số 4 → trạng thái mới 1'),B('Predict 1 → reveal 2 → loss 1','Dự báo 1 → thấy 2 → sai số 1'),B('Update state 1.5; mean loss 2.5','Trạng thái mới 1,5; sai số trung bình 2,5')],B('These nodes reproduce exactly the two-target example.','Các nút dựng lại chính xác ví dụ hai mục tiêu.'))),
S(B('Results text must agree with tables','Văn bản kết quả phải khớp bảng'),B('A percentage reduction needs an explicit denominator. Absolute change and relative change use different units: loss falls from 5 to 4 by 1 loss unit, or 20% of the baseline. Round only after calculating. A table’s sample count and metric must accompany comparisons so unlike quantities are not silently combined.','Mức giảm phần trăm cần mẫu số rõ. Thay đổi tuyệt đối và tương đối khác đơn vị: sai số từ 5 xuống 4 là giảm 1 đơn vị sai số hoặc 20% so với đối chứng. Chỉ làm tròn sau tính toán. Phải kèm số mẫu và thước đo để không âm thầm ghép đại lượng khác nhau.'),B('Supplied table: baseline MSE 1.25, model MSE 1.10, n=200. Absolute reduction=0.15 target-units². Relative reduction=0.15/1.25=12%. Draft text “15% lower MAE on 250 samples” has three errors: percentage, metric and count. Correct all three, and do not invent an uncertainty interval.','Bảng cho trước: MSE đối chứng 1,25, mô hình 1,10, n=200. Giảm tuyệt đối=0,15 đơn vị mục tiêu². Giảm tương đối=0,15/1,25=12%. Câu nháp “MAE thấp hơn 15% trên 250 mẫu” sai ba chỗ: phần trăm, thước đo, số mẫu. Sửa cả ba, không tự bịa khoảng bất định.'),[B('Find and explain the three inconsistencies.','Tìm và giải thích ba chỗ không nhất quán.'),B('Generate a results sentence directly from a JSON table.','Tạo câu kết quả trực tiếp từ bảng JSON.'),B('Solve the percentage exercise with full precision before rounding.','Giải bài phần trăm bằng độ chính xác đầy đủ rồi mới làm tròn.'),B('Audit every numeric sentence in the short methods/results draft.','Kiểm toán mọi câu có số trong bản nháp phương pháp/kết quả.')],B('Baseline MAE=0.8, model MAE=0.7 on 80 forecasts. Report absolute and relative reduction, including units and scope.','MAE đối chứng=0,8, mô hình=0,7 trên 80 dự báo. Báo giảm tuyệt đối, tương đối, đơn vị và phạm vi.'),B('Use 0.8, not 0.7, as the reference denominator.','Dùng 0,8 làm mẫu số tham chiếu, không phải 0,7.'),B('Absolute reduction=0.1 target unit. Relative reduction=0.1/0.8=0.125=12.5%. “On these 80 forecasts, sample MAE fell from 0.8 to 0.7.” No uncertainty or out-of-sample generalization beyond the stated evaluation is supplied.','Giảm tuyệt đối=0,1 đơn vị mục tiêu. Tương đối=0,1/0,8=0,125=12,5%. “Trên 80 dự báo này, MAE mẫu giảm từ 0,8 xuống 0,7.” Chưa có thông tin bất định hay khả năng khái quát ngoài phép đánh giá đã nêu.'),B('results.md generated from a checked results table.','results.md được tạo từ bảng kết quả đã kiểm tra.'),bars(B('Table values, without invented error bars','Giá trị trong bảng, không bịa thanh sai số'),[B('Baseline','Đối chứng'),B('Model','Mô hình')],[1.25,1.1],B('MSE (target units squared)','MSE (bình phương đơn vị mục tiêu)'),B('Both bars summarize the same 200 forecasts; reduction is 12%.','Hai cột tóm tắt cùng 200 dự báo; mức giảm là 12%.'))),
S(B('Related work without overstating novelty','Đối chiếu công trình trước, không phóng đại mới lạ'),B('Related work compares assumptions, methods and evidence, not just titles. A fair comparison describes what a previous result actually claims. A paper that proves a bound under bounded gradients is not refuted by an experiment with unbounded noise; the settings differ. The cards below are fictional summaries, so no external reading is required.','Đối chiếu công trình trước cần so giả định, phương pháp, bằng chứng, không chỉ tiêu đề. So sánh công bằng nêu đúng kết luận trước đó. Định lý dưới gradient bị chặn không bị bác bỏ bởi thí nghiệm có nhiễu không bị chặn; hai bối cảnh khác nhau. Các thẻ dưới đây là tóm tắt giả định nên không cần đọc ngoài.'),B('Card A: projected gradient, bounded gradients, worst-case regret theorem, no experiments. Card B: unprojected update, Gaussian observations, synthetic empirical MSE, no theorem. Our study: two step sizes, Gaussian mean shifts, empirical MSE. It is closest to B in evidence type; it cannot claim to improve A’s theorem unless it proves a comparable bound under stated assumptions.','Thẻ A: gradient có phép chiếu, gradient bị chặn, định lý regret trường hợp xấu nhất, không thí nghiệm. Thẻ B: cập nhật không chiếu, quan sát Gaussian, MSE thực nghiệm giả lập, không định lý. Nghiên cứu ta: hai bước học, đổi trung bình Gaussian, MSE thực nghiệm. Gần B về kiểu bằng chứng; không thể nói cải tiến định lý A nếu chưa chứng minh cận so sánh được dưới giả định rõ.'),[B('Build a three-row assumption/method/evidence table from the cards.','Lập bảng ba hàng giả định/phương pháp/bằng chứng từ các thẻ.'),B('Write one accurate contrast with A and one with B.','Viết một đối chiếu chính xác với A và một với B.'),B('Solve the exercise and identify the unsupported theorem claim.','Giải bài và tìm tuyên bố định lý thiếu căn cứ.'),B('Draft related-work.md using the fictional cards as practice placeholders.','Soạn related-work.md dùng thẻ giả định làm chỗ thực hành.')],B('Card C proves a bound for convex losses. Your code tests a nonconvex neural model and gets lower MSE. Can you state that C’s bound is improved?','Thẻ C chứng minh cận cho hàm mất mát lồi. Mã của bạn thử mạng phi lồi và có MSE thấp hơn. Có thể nói đã cải thiện cận C không?'),B('An empirical error and a theorem’s upper bound are different objects.','Sai số thực nghiệm và cận trên của định lý là hai đối tượng khác nhau.'),B('No. The experiment has different assumptions and reports an empirical metric, not a tighter theorem. State the measured MSE comparison in its own setting. Improving C’s bound requires a proof with comparable assumptions and a clear inequality showing the improvement.','Không. Thí nghiệm khác giả định và báo thước đo thực nghiệm, không phải định lý chặt hơn. Nêu so sánh MSE đã đo trong bối cảnh riêng. Cải thiện cận C cần chứng minh với giả định so sánh được và bất đẳng thức thể hiện phần cải thiện.'),B('related-work.md with explicit assumption boundaries.','related-work.md có ranh giới giả định rõ ràng.'),steps(B('Three dimensions of comparison','Ba chiều đối chiếu'),[B('A: bounded gradients → regret theorem','A: gradient bị chặn → định lý regret'),B('B: Gaussian data → empirical MSE','B: dữ liệu Gaussian → MSE thực nghiệm'),B('Ours: Gaussian shifts → step-size comparison','Ta: đổi Gaussian → so bước học')],B('The diagram organizes supplied cards; it does not rank fictional papers.','Sơ đồ tổ chức thẻ đã cho, không xếp hạng các bài giả định.'))),
S(B('An abstract with evidence and limits','Tóm tắt có bằng chứng và giới hạn'),B('A useful abstract has four moves: question, method, principal result and boundary. Space is limited, so choose the primary result rather than listing every experiment. Limitations should alter the interpretation: synthetic-only evidence is a real scope restriction; “more work is needed” says little.','Tóm tắt hữu ích có bốn bước: câu hỏi, phương pháp, kết quả chính, giới hạn. Dung lượng ngắn nên chọn kết quả chính thay vì kể mọi thí nghiệm. Hạn chế phải tác động đến diễn giải: chỉ có bằng chứng giả lập là giới hạn thật; “cần nghiên cứu thêm” nói rất ít.'),B('Record: 20 synthetic streams, two step sizes, first 10 post-shift steps, mean difference −0.2 MSE units with interval [−0.35,−0.05]; no market data. Abstract skeleton: ask about faster adaptation; describe paired stream evaluation; report the estimate and interval; limit the conclusion to this generator and horizon. Do not add profitability or universal optimality.','Bản ghi: 20 chuỗi giả lập, hai bước học, 10 bước đầu sau đổi, chênh lệch −0,2 đơn vị MSE với khoảng [−0,35;−0,05]; không có dữ liệu thị trường. Khung tóm tắt: hỏi về thích nghi nhanh; mô tả đánh giá ghép cấp chuỗi; báo ước lượng và khoảng; giới hạn vào bộ sinh và chân trời này. Không thêm lợi nhuận hay tối ưu phổ quát.'),[B('Write one sentence for each of the four abstract moves.','Viết một câu cho mỗi bước của tóm tắt.'),B('Check every abstract number against the supplied record.','So mọi số trong tóm tắt với bản ghi.'),B('Solve the exercise, keeping the negative result visible.','Giải bài, giữ kết quả âm hiện rõ.'),B('Assemble manuscript-v1.md from introduction, methods, results and limits.','Ghép manuscript-v1.md từ mở đầu, phương pháp, kết quả, giới hạn.')],B('Given 10 streams and difference +0.3 with interval [0.1,0.5], write a results-and-limits sentence under d=fast−slow.','Cho 10 chuỗi và chênh lệch +0,3 với khoảng [0,1;0,5], viết câu kết quả và giới hạn khi d=nhanh−chậm.'),B('A positive loss difference means the fast method is worse.','Chênh lệch sai số dương nghĩa là phương pháp nhanh tệ hơn.'),B('“Across 10 synthetic streams, the fast update had 0.3 higher mean loss than the slow update, with supplied interval [0.1,0.5]; the conclusion applies to this generator and evaluation horizon.” This reports the unfavorable finding rather than redefining the target after evaluation.','“Trên 10 chuỗi giả lập, cập nhật nhanh có sai số trung bình cao hơn cập nhật chậm 0,3, với khoảng đã cho [0,1;0,5]; kết luận giới hạn ở bộ sinh và chân trời đánh giá này.” Câu báo kết quả bất lợi thay vì đổi mục tiêu sau đánh giá.'),B('manuscript-v1.md with a claim-audited abstract.','manuscript-v1.md có tóm tắt đã kiểm tra từng kết luận.'),steps(B('Four-sentence abstract plan','Kế hoạch tóm tắt bốn câu'),[B('Question: faster post-shift adaptation?','Câu hỏi: thích nghi sau đổi nhanh hơn?'),B('Method: 20 paired synthetic streams','Phương pháp: 20 chuỗi giả lập ghép cặp'),B('Result: difference −0.2, interval [−0.35,−0.05]','Kết quả: −0,2, khoảng [−0,35;−0,05]'),B('Scope: this generator and first 10 steps','Phạm vi: bộ sinh này và 10 bước đầu')],B('Every number comes from the supplied record; the interval is not recomputed from absent raw data.','Mọi số lấy từ bản ghi; không tính lại khoảng từ dữ liệu thô chưa được cung cấp.')))
]));

modules.push(M(97,B('Adversarial methodological review','Phản biện phương pháp nghiêm khắc'),B('A methodological review tries to find alternative explanations for a result. It is not an attack on the author. Separate validity defects, which can invalidate a comparison, from clarity defects, which make a valid comparison hard to inspect. A useful review includes a reproducible counterexample and a specific repair. This week provides all review cases and expected inputs so no outside reviewer is required.','Phản biện phương pháp tìm cách giải thích khác cho kết quả, không công kích tác giả. Tách lỗi tính hợp lệ có thể làm hỏng so sánh khỏi lỗi diễn đạt khiến so sánh đúng khó kiểm tra. Phản biện hữu ích có phản ví dụ tái lập được và cách sửa cụ thể. Tuần này cung cấp đủ tình huống phản biện và đầu vào, không bắt buộc người đánh giá bên ngoài.'),[
S(B('Audit feature availability','Kiểm tra lúc đặc trưng có sẵn'),B('A timestamp saying which period a value describes is not necessarily its publication time. A forecast may use a feature only if the feature was actually available before the decision. Revised historical data can also leak later knowledge. Record event time, release time and decision time separately.','Mốc thời gian cho biết giá trị mô tả kỳ nào chưa chắc là lúc công bố. Dự báo chỉ được dùng đặc trưng thực sự có trước quyết định. Dữ liệu lịch sử đã sửa cũng có thể lộ thông tin tương lai. Ghi riêng thời điểm sự kiện, công bố và quyết định.'),B('A monthly statistic describes January but is released February 5. A forecast is issued February 1. Joining by “January” makes the value look historical, yet it is four days unavailable at decision time. The fixture should reject release_time > forecast_time, regardless of the event month.','Thống kê mô tả tháng Một nhưng công bố ngày 5/2. Dự báo phát ngày 1/2. Ghép theo “tháng Một” khiến số liệu có vẻ lịch sử, nhưng lúc quyết định vẫn chưa có trong bốn ngày nữa. Kiểm thử phải từ chối release_time > forecast_time dù tháng sự kiện ở quá khứ.'),[B('Draw event, decision and release dates on a timeline.','Vẽ mốc sự kiện, quyết định, công bố trên trục thời gian.'),B('Write an as-of join test that rejects the February 5 release.','Viết kiểm thử ghép theo thời điểm, từ chối bản công bố 5/2.'),B('Solve the exercise including equality at the cutoff.','Giải bài, xét cả trường hợp bằng mốc cắt.'),B('Write a review comment with severity, reproduction and repair.','Viết nhận xét có mức độ, cách tái hiện và cách sửa.')],B('Decision is 09:00; releases are 08:55, 09:00 and 09:05. A protocol requires strictly earlier availability. Which rows qualify and why?','Quyết định lúc 09:00; công bố lúc 08:55, 09:00, 09:05. Giao thức yêu cầu có sẵn sớm hơn nghiêm ngặt. Hàng nào hợp lệ, vì sao?'),B('The rule is release < decision, not ≤.','Quy tắc là công bố < quyết định, không phải ≤.'),B('Only 08:55 qualifies. The 09:00 row fails the explicitly strict boundary; 09:05 is in the future. If simultaneous releases are intended to be usable, the protocol needs a documented ordering and latency model rather than silently changing the inequality.','Chỉ 08:55 hợp lệ. Hàng 09:00 không thỏa ranh giới nghiêm ngặt; 09:05 ở tương lai. Nếu muốn dùng công bố đồng thời, giao thức cần quy định thứ tự và độ trễ, không âm thầm đổi dấu bất đẳng thức.'),B('availability-review.md and boundary tests.','availability-review.md và kiểm thử ranh giới.'),steps(B('A historical month can still leak','Tháng quá khứ vẫn có thể gây rò rỉ'),[B('January: event period','Tháng Một: kỳ sự kiện'),B('February 1: forecast decision','1/2: quyết định dự báo'),B('February 5: statistic released too late','5/2: thống kê công bố quá muộn')],B('Chronological order of the exact dates in the example.','Thứ tự thời gian đúng các ngày trong ví dụ.'))),
S(B('Challenge a weak baseline','Thách thức đối chứng yếu'),B('An improvement over a weak comparator may say little about the proposed method. A baseline must follow the same information constraints and receive a reasonable, disclosed tuning budget. Simple persistence is often informative for slowly changing series. Adding it is a validity check, not a guarantee that it will always win.','Thắng đối chứng yếu có thể chưa nói nhiều về phương pháp mới. Đối chứng phải tuân cùng giới hạn thông tin và có ngân sách tinh chỉnh hợp lý, công khai. Dự báo giữ giá trị gần nhất thường hữu ích với chuỗi đổi chậm. Thêm nó là kiểm tra tính hợp lệ, không bảo đảm nó luôn thắng.'),B('Targets=[10,11,12]. Zero baseline forecasts=[0,0,0], squared losses=[100,121,144], mean 365/3. Model forecasts=[9,9,9], losses=[1,4,9], mean 14/3. Persistence forecasts=[9,10,11] using supplied prior values, losses=[1,1,1], mean 1. The model beats zero but loses to persistence.','Mục tiêu=[10,11,12]. Đối chứng 0 dự báo=[0,0,0], sai số bình phương=[100,121,144], trung bình 365/3. Mô hình dự báo=[9,9,9], sai số=[1,4,9], trung bình 14/3. Giữ giá trị trước dự báo=[9,10,11] theo giá trị quá khứ đã cho, sai số=[1,1,1], trung bình 1. Mô hình thắng 0 nhưng thua giữ giá trị trước.'),[B('Compute each baseline’s three losses by hand.','Tự tính ba sai số của từng đối chứng.'),B('Implement the shared scoring function and verify no future target is used.','Viết hàm chấm chung, kiểm tra không dùng mục tiêu tương lai.'),B('Solve the exercise and rank models by the declared metric.','Giải bài, xếp mô hình theo thước đo đã khai báo.'),B('Write a baseline review explaining how the conclusion changes.','Viết phản biện đối chứng, giải thích kết luận thay đổi ra sao.')],B('Targets=[4,5], model=[3,3], persistence=[3,4], zero=[0,0]. Compute MSE and state the fair conclusion.','Mục tiêu=[4,5], mô hình=[3,3], giữ giá trị trước=[3,4], đối chứng 0=[0,0]. Tính MSE và kết luận công bằng.'),B('Square first, then average over the same two targets.','Bình phương trước rồi lấy trung bình trên cùng hai mục tiêu.'),B('Model MSE=(1+4)/2=2.5; persistence=(1+1)/2=1; zero=(16+25)/2=20.5. The model improves over zero but not persistence on these two targets. A broad superiority claim is unsupported, even though the zero-baseline percentage improvement is large.','MSE mô hình=(1+4)/2=2,5; giữ giá trị trước=(1+1)/2=1; đối chứng 0=(16+25)/2=20,5. Mô hình hơn 0 nhưng kém giữ giá trị trước trên hai mục tiêu này. Kết luận vượt trội rộng không có căn cứ dù phần trăm cải thiện so 0 rất lớn.'),B('baseline-review.md and a common scoring fixture.','baseline-review.md và bộ chấm chung.'),bars(B('Same targets, three comparators','Cùng mục tiêu, ba phương pháp'),[B('Zero','Dự báo 0'),B('Model','Mô hình'),B('Persistence','Giữ giá trị trước')],[365/3,14/3,1],B('MSE (units squared)','MSE (đơn vị bình phương)'),B('Exact example MSE; zero-based bars preserve the large baseline gap.','MSE đúng ví dụ; cột bắt đầu từ 0 để giữ đúng chênh lệch lớn.'))),
S(B('Selection can manufacture a winner','Lựa chọn có thể tạo người thắng giả'),B('Testing many ideas and reporting only the best increases false discoveries. For m independent tests each with false-positive probability α, probability of at least one false positive is 1−(1−α)^m. Independence is an assumption here. A union bound mα does not require independence, though it can be loose.','Thử nhiều ý tưởng rồi chỉ báo tốt nhất làm tăng phát hiện sai. Với m kiểm định độc lập, mỗi kiểm định có xác suất dương tính giả α, xác suất ít nhất một dương tính giả là 1−(1−α)^m. Độc lập là giả định ở đây. Cận hợp mα không cần độc lập nhưng có thể lỏng.'),B('With m=20 and α=0.05 under all nulls and independence, no false positive has probability 0.95²⁰≈0.3585. At least one has probability ≈0.6415. This does not mean a particular reported finding has 64% probability of being false; it is a repeated-testing event under the assumed null setup.','Với m=20, α=0,05 khi mọi giả thuyết không đều đúng và độc lập, không có dương tính giả có xác suất 0,95²⁰≈0,3585. Ít nhất một có xác suất ≈0,6415. Điều này không nói một kết quả cụ thể có 64% xác suất sai; đây là sự kiện thử lặp dưới bối cảnh giả thuyết không đã nêu.'),[B('Derive the complement probability before using a calculator.','Suy ra xác suất biến cố bù trước khi dùng máy tính.'),B('Plot 1−0.95^m for m=1 through 20.','Vẽ 1−0,95^m với m từ 1 đến 20.'),B('Solve the exercise and contrast independence with a union bound.','Giải bài, phân biệt độc lập với cận hợp.'),B('Design an experiment registry that retains failed runs and untouched validation.','Thiết kế sổ thí nghiệm giữ lần thất bại và tập xác nhận chưa đụng tới.')],B('For five independent tests, assuming all five null hypotheses are true and each test uses α=0.05, compute the chance of at least one false positive and the union bound.','Với năm kiểm định độc lập ở mức α=0,05 và giả sử cả năm giả thuyết không đều đúng, tính xác suất có ít nhất một dương tính giả và cận hợp.'),B('Use 1−0.95^5 and compare with 5×0.05.','Dùng 1−0,95^5 và so với 5×0,05.'),B('Exact under independence: 1−0.95⁵=0.226219≈22.62%. Union bound=0.25=25%, valid even without independence. The bound is larger because it can count overlapping false-positive events more than once.','Chính xác dưới độc lập: 1−0,95⁵=0,226219≈22,62%. Cận hợp=0,25=25%, vẫn đúng khi không độc lập. Cận lớn hơn vì có thể đếm lặp các sự kiện dương tính giả giao nhau.'),B('selection-review.md with assumptions and a run registry schema.','selection-review.md có giả định và cấu trúc sổ lần chạy.'),{kind:'xy',title:B('Repeated-test false-positive risk','Rủi ro dương tính giả khi thử lặp'),xLabel:B('Number of independent tests','Số kiểm định độc lập'),yLabel:B('Probability of at least one false positive','Xác suất ít nhất một dương tính giả'),series:[{name:B('1 − 0.95^m','1 − 0,95^m'),mode:'line',points:Array.from({length:20},(_,i)=>[i+1,1-.95**(i+1)])}],caption:B('Exact formula under independent true nulls at α=0.05; not the posterior probability that a selected result is false.','Công thức đúng dưới các giả thuyết không đúng và độc lập với α=0,05; không phải xác suất hậu nghiệm kết quả được chọn là sai.')}),
S(B('A metric implementation can change the answer','Cài đặt thước đo có thể đổi đáp án'),B('RMSE is sqrt(mean(error²)); mean absolute error is mean(|error|). Averaging row-level square roots of squared errors computes MAE, not RMSE. Names in code are not evidence of correct implementation. Use a fixture where errors have unequal magnitudes so the two metrics differ.','RMSE là sqrt(mean(error²)); MAE là mean(|error|). Lấy căn sai số bình phương từng hàng rồi trung bình sẽ ra MAE, không phải RMSE. Tên biến trong mã không chứng minh cài đúng. Dùng dữ liệu thử có độ lớn sai số khác nhau để hai thước đo tách biệt.'),B('Errors=[0,4]. Correct RMSE=sqrt((0+16)/2)=sqrt(8)≈2.828. The buggy expression mean(sqrt(error²))=(0+4)/2=2. Both return 0 on perfect predictions, so a zero-only test would miss this bug.','Sai số=[0,4]. RMSE đúng=sqrt((0+16)/2)=sqrt(8)≈2,828. Biểu thức lỗi mean(sqrt(error²))=(0+4)/2=2. Cả hai trả 0 khi dự báo hoàn hảo nên chỉ kiểm thử toàn số 0 sẽ bỏ sót lỗi.'),[B('Derive both formulas and identify the misplaced square root.','Suy ra hai công thức, xác định căn đặt sai chỗ.'),B('Write tests for errors [0,4], [−3,3] and [0,0].','Viết kiểm thử sai số [0,4], [−3,3], [0,0].'),B('Solve the exercise and state output units.','Giải bài và nêu đơn vị đầu ra.'),B('Write a defect report naming all tables that depend on the buggy metric.','Viết báo lỗi nêu mọi bảng phụ thuộc thước đo sai.')],B('For errors [−1,3], calculate MAE, MSE and RMSE. Which quantity equals the buggy row-root average?','Với sai số [−1,3], tính MAE, MSE, RMSE. Đại lượng nào bằng trung bình căn từng hàng bị gắn nhãn sai?'),B('The square root must come after averaging for RMSE.','Với RMSE, phải lấy căn sau khi trung bình.'),B('MAE=(1+3)/2=2; MSE=(1+9)/2=5; RMSE=√5≈2.236. The buggy expression gives MAE=2. MAE and RMSE use target units; MSE uses squared target units. Equal-magnitude errors would not distinguish the formulas.','MAE=(1+3)/2=2; MSE=(1+9)/2=5; RMSE=√5≈2,236. Biểu thức lỗi cho MAE=2. MAE, RMSE cùng đơn vị mục tiêu; MSE là đơn vị bình phương. Sai số có độ lớn bằng nhau không phân biệt được hai công thức.'),B('metric-bug.md and unequal-error regression tests.','metric-bug.md và kiểm thử hồi quy sai số không đều.'),steps(B('Where the square root belongs','Căn bậc hai phải đặt ở đâu'),[B('Errors [0,4] → squares [0,16]','Sai số [0,4] → bình phương [0,16]'),B('Mean squares = 8','Trung bình bình phương = 8'),B('Square root last → RMSE √8','Lấy căn cuối → RMSE √8')],B('The order of operations reproduces the correct metric.','Thứ tự thao tác dựng lại đúng thước đo.'))),
S(B('Prioritize review findings','Ưu tiên phát hiện phản biện'),B('Severity depends on how a defect changes the scientific conclusion. A leakage bug can invalidate every result; a mislabeled axis may leave calculations valid but communication wrong. A review should distinguish confirmed defects from questions and assign a concrete acceptance test to each requested repair.','Mức độ phụ thuộc lỗi làm đổi kết luận khoa học thế nào. Rò rỉ có thể làm hỏng mọi kết quả; nhãn trục sai có thể giữ phép tính đúng nhưng truyền đạt sai. Phản biện cần tách lỗi đã xác nhận khỏi câu hỏi, gắn phép kiểm tra chấp nhận cụ thể với mỗi yêu cầu sửa.'),B('Provided review: F1 uses tomorrow’s target as a feature; F2 says “percent” where values are fractions; F3 requests a new model without explaining relevance. Priority: block conclusions for F1 and rerun after repair; fix F2 with a unit test and labels; ask F3 which hypothesis the extra model tests. More experiments do not repair F1.','Phản biện cho trước: F1 dùng mục tiêu ngày mai làm đặc trưng; F2 ghi “phần trăm” nhưng số là tỷ lệ; F3 yêu cầu mô hình mới mà không nói liên quan gì. Ưu tiên: chặn kết luận vì F1 và chạy lại sau sửa; sửa F2 bằng kiểm thử đơn vị, nhãn; hỏi F3 mô hình thêm kiểm tra giả thuyết nào. Thêm thí nghiệm không sửa được F1.'),[B('Classify the three comments as validity, presentation or unresolved request.','Phân loại ba nhận xét: tính hợp lệ, trình bày, yêu cầu chưa rõ.'),B('Write one acceptance test for F1 and F2.','Viết một kiểm tra chấp nhận cho F1, F2.'),B('Solve the exercise and justify ordering by impact.','Giải bài, biện minh thứ tự theo tác động.'),B('Assemble method-review.md with five alternative explanations for an apparent gain.','Tạo method-review.md có năm cách giải thích khác cho cải thiện có vẻ quan sát được.')],B('Review finds a shuffled time split, a typo in the title and a missing seed value. Rank repairs and state what must be rerun.','Phản biện thấy chia thời gian bị xáo trộn, lỗi chữ tiêu đề, thiếu seed. Xếp ưu tiên và nêu phần phải chạy lại.'),B('Repair validity before reproducibility metadata and cosmetic wording.','Sửa tính hợp lệ trước metadata tái lập và câu chữ thẩm mỹ.'),B('First replace the shuffled split with the declared chronological protocol and rerun all affected evaluation. Next recover or explicitly mark the missing seed; if the run cannot be identified, regenerate it under a recorded seed. Fix the title typo without rerunning numerical work. Preserve old outputs as invalidated evidence rather than erasing the history.','Trước hết thay chia xáo trộn bằng giao thức thời gian và chạy lại toàn bộ đánh giá bị ảnh hưởng. Sau đó khôi phục hoặc ghi rõ seed thiếu; nếu không xác định được lần chạy, tạo lại với seed được lưu. Sửa lỗi tiêu đề không cần chạy lại tính toán. Giữ đầu ra cũ với nhãn mất hiệu lực thay vì xóa lịch sử.'),B('method-review.md with prioritized, testable revisions.','method-review.md có sửa đổi ưu tiên và kiểm tra được.'),steps(B('Repair by scientific impact','Sửa theo tác động khoa học'),[B('F1: leakage → block claims and rerun','F1: rò rỉ → chặn kết luận, chạy lại'),B('F2: unit label → correct and test display','F2: nhãn đơn vị → sửa, kiểm tra hiển thị'),B('F3: extra model → request a hypothesis','F3: mô hình thêm → yêu cầu giả thuyết')],B('Priority is based on the supplied defects, not a numerical severity scale.','Ưu tiên dựa trên lỗi đã cho, không phải thang mức độ số học.')))
]));

modules.push(M(98,B('Revise without selecting a convenient story','Sửa nghiên cứu mà không chọn câu chuyện có lợi'),B('A revision should have a reason independent of whether it makes the method look better. Correcting leakage restores validity; trying additional parameters after a disappointing result changes the research process and must be labeled exploratory. Preserve the previous version, describe the change and identify which outputs depend on it. A transparent unfavorable correction is more informative than an unexplained improved score.','Sửa đổi cần lý do độc lập với việc có làm phương pháp trông tốt hơn không. Sửa rò rỉ khôi phục tính hợp lệ; thử thêm tham số sau kết quả thất vọng làm đổi quá trình nghiên cứu và phải ghi là khám phá. Giữ phiên bản trước, mô tả thay đổi, xác định đầu ra phụ thuộc. Sửa đúng nhưng bất lợi một cách minh bạch có giá trị hơn điểm tốt lên không giải thích.'),[
S(B('Correction or new exploration?','Sửa lỗi hay khám phá mới?'),B('Classify changes by their cause. A bug fix restores the originally intended procedure. An amendment changes a planned procedure for a stated reason. Exploration asks a new question after seeing data. These categories can coexist in a project, but calling all changes “bug fixes” conceals researcher choices.','Phân loại theo nguyên nhân. Sửa lỗi khôi phục thủ tục dự định ban đầu. Sửa giao thức thay thủ tục đã định vì lý do được nêu. Khám phá hỏi câu mới sau khi xem dữ liệu. Các loại có thể cùng tồn tại, nhưng gọi tất cả là “sửa lỗi” che giấu lựa chọn của người nghiên cứu.'),B('C1 corrects RMSE implemented as MAE: bug fix. C2 adds five learning rates because the original rate lost: exploration. C3 shortens the evaluation horizon because later targets are permanently missing: amendment requiring justification and a new target definition. None should overwrite the original protocol silently.','C1 sửa RMSE bị cài thành MAE: sửa lỗi. C2 thêm năm bước học vì bước cũ thua: khám phá. C3 rút chân trời đánh giá vì mục tiêu muộn bị thiếu vĩnh viễn: sửa giao thức, cần lý do và định nghĩa mục tiêu mới. Không thay đổi nào được âm thầm ghi đè giao thức gốc.'),[B('Write the cause and category for C1–C3.','Viết nguyên nhân, loại cho C1–C3.'),B('Create a change record with old rule, new rule and affected results.','Tạo bản ghi có quy tắc cũ, mới và kết quả bị ảnh hưởng.'),B('Solve the exercise and separate validity repair from model search.','Giải bài, tách sửa tính hợp lệ khỏi tìm mô hình.'),B('Draft revision-log.md preserving the original protocol.','Soạn revision-log.md giữ giao thức ban đầu.')],B('After seeing poor results, an author changes random seed until loss falls. Is this a correction? How should the work be reported?','Sau kết quả kém, tác giả đổi seed đến khi sai số giảm. Đây có phải sửa lỗi? Nên báo thế nào?'),B('Ask whether the original seed was invalid or merely unfavorable.','Hỏi seed ban đầu sai hay chỉ cho kết quả bất lợi.'),B('It is selection/exploration unless a concrete seed-related defect was established. Retain every attempted seed and report a prespecified aggregate or a clearly exploratory distribution. Do not present the selected minimum as an ordinary single-run estimate; validate any new procedure on untouched runs.','Đây là lựa chọn/khám phá nếu chưa xác nhận lỗi cụ thể liên quan seed. Giữ mọi seed đã thử, báo tổng hợp định trước hoặc phân phối mang nhãn khám phá. Không trình bày giá trị nhỏ nhất được chọn như ước lượng một lần chạy bình thường; kiểm chứng thủ tục mới trên lần chạy chưa dùng.'),B('A categorized revision log with explicit motivations.','Nhật ký sửa đổi được phân loại, có động cơ rõ.'),steps(B('Three supplied changes','Ba thay đổi đã cho'),[B('C1 wrong formula → correction','C1 sai công thức → sửa lỗi'),B('C2 more rates after loss → exploration','C2 thêm bước học sau khi thua → khám phá'),B('C3 missing outcomes → justified amendment','C3 thiếu kết quả → sửa giao thức có lý do')],B('These are categories, not a ranking of whether the new score improves.','Đây là phân loại, không xếp theo điểm mới có tốt hơn không.'))),
S(B('Rerun the dependency closure','Chạy lại toàn bộ phần phụ thuộc'),B('Outputs form a directed dependency graph. If a node changes, every descendant may be stale. A changed metric requires rescoring and rebuilding dependent tables and figures, but may not require retraining if saved predictions remain valid. Rerunning only the favorable figure leaves an inconsistent manuscript.','Đầu ra tạo đồ thị phụ thuộc có hướng. Khi một nút đổi, mọi nút con cháu có thể lỗi thời. Đổi thước đo cần chấm lại và dựng lại bảng, hình phụ thuộc, nhưng có thể không cần huấn luyện lại nếu dự báo đã lưu còn hợp lệ. Chỉ chạy lại hình có lợi khiến bản thảo không nhất quán.'),B('Graph: raw D → predictions P → metric M → table T → figure F → abstract A. A separate runtime log R depends on P only. Fixing M invalidates M,T,F,A; D,P,R remain usable under the stated assumption that predictions were correct. Changing feature construction inside P would invalidate P and all its descendants, including R.','Đồ thị: dữ liệu D → dự báo P → thước đo M → bảng T → hình F → tóm tắt A. Nhật ký thời gian R chỉ phụ thuộc P. Sửa M làm M,T,F,A mất hiệu lực; D,P,R còn dùng được nếu dự báo đúng. Đổi tạo đặc trưng trong P làm P và mọi hậu duệ mất hiệu lực, gồm R.'),[B('Draw the graph and mark descendants of M.','Vẽ đồ thị, đánh dấu hậu duệ của M.'),B('Implement descendant traversal on an adjacency list.','Viết duyệt hậu duệ trên danh sách kề.'),B('Solve the exercise and compare the two rerun sets.','Giải bài, so hai tập phải chạy lại.'),B('Write a rerun plan that names reusable and invalidated artifacts.','Viết kế hoạch chạy lại, nêu hiện vật dùng lại được và mất hiệu lực.')],B('D→P, P→M, M→T, M→F, T→A, F→A. If T’s formatting changes without altering values, which descendants need rebuilding? If M changes, what expands?','D→P, P→M, M→T, M→F, T→A, F→A. Nếu chỉ đổi định dạng T không đổi số, hậu duệ nào cần dựng lại? Nếu đổi M thì tập mở rộng ra sao?'),B('Follow arrows forward from the changed node.','Đi theo mũi tên từ nút bị đổi.'),B('A formatting change rebuilds T and A if A embeds T; P,M,F remain valid. A change to M requires M,T,F,A. Neither case requires retraining P when its stored predictions and inputs are unchanged. Dependencies should be explicit rather than guessed from filenames.','Đổi định dạng dựng lại T và A nếu A nhúng T; P,M,F còn đúng. Đổi M cần M,T,F,A. Cả hai không cần huấn luyện P nếu dự báo lưu và đầu vào không đổi. Phụ thuộc cần khai báo rõ thay vì đoán theo tên tệp.'),B('rerun-plan.json and a dependency traversal test.','rerun-plan.json và kiểm thử duyệt phụ thuộc.'),steps(B('Metric correction propagation','Lan truyền sửa thước đo'),[B('Reuse D and correct predictions P','Dùng lại D và dự báo P đúng'),B('Recompute metric M','Tính lại thước đo M'),B('Rebuild table T and figure F','Dựng lại bảng T và hình F'),B('Update abstract A; retain runtime R','Cập nhật tóm tắt A; giữ nhật ký R')],B('Matches the supplied graph and assumes prediction generation is unaffected.','Khớp đồ thị đã cho, giả định tạo dự báo không bị ảnh hưởng.'))),
S(B('Report before and after honestly','Báo trước và sau trung thực'),B('A correction table keeps old and new values side by side and labels the old result invalid. The change in the conclusion matters more than whether the code diff is small. Use paired comparisons against the same corrected baseline, because a fix may affect both methods.','Bảng sửa lỗi giữ số cũ, mới cạnh nhau và đánh dấu kết quả cũ không hợp lệ. Thay đổi kết luận quan trọng hơn số dòng mã sửa. So ghép với cùng đối chứng đã sửa vì lỗi có thể ảnh hưởng cả hai phương pháp.'),B('Old flawed scores: model 0.8, baseline 1.0, difference −0.2. After leakage repair: model 1.2, baseline 1.0, difference +0.2. The apparent advantage reverses. Report “the earlier improvement was invalidated by leakage correction,” not “performance was slightly adjusted.”','Điểm cũ lỗi: mô hình 0,8, đối chứng 1,0, chênh lệch −0,2. Sau sửa rò rỉ: mô hình 1,2, đối chứng 1,0, chênh lệch +0,2. Lợi thế có vẻ có đã đảo chiều. Báo “cải thiện trước mất hiệu lực sau sửa rò rỉ”, không phải “hiệu suất được điều chỉnh nhẹ”.'),[B('Compute old and new paired differences.','Tính chênh lệch ghép trước, sau.'),B('Make a correction table with validity status and source IDs.','Lập bảng sửa có trạng thái hợp lệ và ID nguồn.'),B('Solve the exercise where both methods change.','Giải bài mà cả hai phương pháp đều đổi.'),B('Rewrite the abstract and conclusion to match corrected evidence.','Sửa tóm tắt, kết luận cho khớp bằng chứng đã sửa.')],B('Old scores A=2,B=3; corrected A=4,B=3.5. Compute both differences d=A−B and explain the conclusion change.','Điểm cũ A=2,B=3; đã sửa A=4,B=3,5. Tính hai chênh lệch d=A−B, giải thích kết luận đổi ra sao.'),B('Compare within each version, not corrected A against old B.','So trong từng phiên bản, không so A mới với B cũ.'),B('Old d=−1 favors A. Corrected d=+0.5 favors B. The old comparison is superseded, and the correction reverses the sample ranking. Keeping only A’s change from 2 to 4 would miss that the baseline also changed.','d cũ=−1 lợi cho A. d đã sửa=+0,5 lợi cho B. So sánh cũ bị thay thế, sửa lỗi đảo thứ hạng mẫu. Chỉ nhìn A từ 2 lên 4 sẽ bỏ qua việc đối chứng cũng đổi.'),B('before-after.csv and an explicit correction paragraph.','before-after.csv và đoạn công bố sửa lỗi rõ ràng.'),bars(B('The comparison reverses after repair','So sánh đảo chiều sau sửa'),[B('Old: invalid','Cũ: không hợp lệ'),B('Corrected','Đã sửa')],[-.2,.2],B('Model loss − baseline loss','Sai số mô hình − đối chứng'),B('Synthetic example; the old negative bar is retained only for the correction record.','Ví dụ giả định; giữ cột âm cũ chỉ để lưu hồ sơ sửa lỗi.'))),
S(B('Keep new hypotheses separate','Tách giả thuyết mới'),B('After discovering a subgroup pattern, testing the same subgroup on the same data is not independent confirmation. Freeze the new hypothesis and evaluate on untouched data generated or held out under an explicit rule. If no fresh data remain, report exploration and uncertainty rather than manufacture a confirmatory label.','Sau khi phát hiện mẫu hình nhóm con, kiểm tra lại cùng nhóm trên cùng dữ liệu không phải xác nhận độc lập. Chốt giả thuyết mới và đánh giá trên dữ liệu chưa đụng tới được sinh hoặc giữ lại theo quy tắc rõ. Nếu hết dữ liệu mới, báo khám phá và bất định thay vì gắn nhãn xác nhận giả.'),B('Runs 1–20 suggested η=0.5 helps only when shift size ≥3. Write H2 before runs 21–40: compare η=0.5 vs 0.1 on shift sizes 3 and 5, average paired MSE across all 20 new runs. Do not delete new runs where the effect reverses or move the threshold to 4 after seeing them.','Lần chạy 1–20 gợi ý η=0,5 chỉ tốt khi độ đổi ≥3. Viết H2 trước lần 21–40: so η=0,5 với 0,1 ở độ đổi 3,5, trung bình MSE ghép trên cả 20 lần mới. Không xóa lần hiệu ứng đảo chiều hay chuyển ngưỡng sang 4 sau khi xem.'),[B('Write H2 including threshold, comparator and aggregation.','Viết H2 gồm ngưỡng, đối chứng, cách tổng hợp.'),B('Design separate discovery and confirmation folders with immutable manifests.','Thiết kế thư mục khám phá, xác nhận riêng có manifest cố định.'),B('Solve the exercise and mark which data remain untouched.','Giải bài, đánh dấu dữ liệu còn chưa dùng.'),B('Write a stopping rule before any new simulated outcome is inspected.','Viết quy tắc dừng trước khi xem kết quả giả lập mới.')],B('You inspected runs 1–30 to choose a threshold, then call runs 21–30 a holdout. Explain the problem and repair options.','Bạn xem lần 1–30 để chọn ngưỡng rồi gọi lần 21–30 là holdout. Giải thích lỗi và cách sửa.'),B('A holdout loses that role once it informs the choice.','Holdout mất vai trò đó khi đã ảnh hưởng lựa chọn.'),B('Runs 21–30 helped choose the threshold, so they are discovery data. Either collect/generate a genuinely untouched set after freezing the rule, or label the current result exploratory. Renaming files does not remove the information already used in selection.','Lần 21–30 đã góp phần chọn ngưỡng nên là dữ liệu khám phá. Hoặc thu/sinh tập thật sự chưa dùng sau khi chốt quy tắc, hoặc ghi kết quả hiện tại là khám phá. Đổi tên tệp không xóa thông tin đã dùng trong lựa chọn.'),B('hypothesis-H2.md with a prospective evaluation rule.','hypothesis-H2.md có quy tắc đánh giá định trước.'),steps(B('Discovery precedes confirmation','Khám phá đi trước xác nhận'),[B('Runs 1–20: discover threshold 3','Lần 1–20: phát hiện ngưỡng 3'),B('Freeze H2 and scoring rule','Chốt H2 và quy tắc chấm'),B('Runs 21–40: untouched evaluation','Lần 21–40: đánh giá chưa dùng'),B('Report all new runs, including failures','Báo mọi lần mới, gồm thất bại')],B('Run ranges are exact roles in the example, not historical project results.','Khoảng lần chạy là vai trò trong ví dụ, không phải kết quả dự án thật.'))),
S(B('Answer a reviewer with a verifiable change','Trả lời phản biện bằng thay đổi kiểm chứng được'),B('A response letter links each comment to a decision, a concrete change and evidence. Agreement without action is incomplete. Disagreement can be reasonable when explained with the study’s scope and evidence. Avoid promising a fix that the manuscript or code does not actually contain.','Thư trả lời nối mỗi nhận xét với quyết định, thay đổi cụ thể, bằng chứng. Đồng ý mà không hành động là chưa đủ. Không đồng ý có thể hợp lý nếu giải thích bằng phạm vi và bằng chứng. Tránh hứa sửa khi bản thảo hoặc mã chưa thực sự có.'),B('Comment R1: “The figure uses a shuffled split.” Response: “Confirmed. We replaced it with the chronological split in protocol P2, reran results E4–E9, and replaced Figure 2. The mean difference changed from −0.2 to +0.1; the superiority claim was removed.” This response identifies the defect, repair, affected evidence and changed conclusion.','Nhận xét R1: “Hình dùng chia mẫu xáo trộn.” Trả lời: “Đã xác nhận. Chúng tôi thay bằng chia thời gian trong P2, chạy lại E4–E9, thay Hình 2. Chênh lệch trung bình đổi từ −0,2 sang +0,1; đã bỏ kết luận vượt trội.” Câu trả lời nêu lỗi, sửa, bằng chứng ảnh hưởng, kết luận đổi.'),[B('Annotate the four parts of the supplied response.','Chú thích bốn phần của câu trả lời đã cho.'),B('Create a response table linking R1 to P2, E4–E9 and Figure 2.','Tạo bảng nối R1 với P2, E4–E9, Hình 2.'),B('Solve the exercise and avoid claiming an unperformed rerun.','Giải bài, không tuyên bố đã chạy lại khi chưa làm.'),B('Assemble manuscript-v2.md and a response letter consistent with the revision log.','Ghép manuscript-v2.md và thư trả lời khớp nhật ký sửa.')],B('A reviewer asks for market profitability, but your study has synthetic forecasts and no execution data. Write a respectful, evidence-based response.','Người phản biện yêu cầu lợi nhuận thị trường, nhưng nghiên cứu chỉ có dự báo giả lập, không có dữ liệu thực hiện lệnh. Viết trả lời tôn trọng và có căn cứ.'),B('You can narrow the claim instead of inventing unavailable evidence.','Có thể thu hẹp kết luận thay vì bịa bằng chứng chưa có.'),B('“We cannot estimate executable profitability from these synthetic forecast records. We have removed trading-performance language and now state that the study measures forecast loss under the specified generator. Execution-aware evaluation is a separate future study requiring prices, fills and costs.” This addresses the concern through an honest scope correction.','“Chúng tôi không thể ước lượng lợi nhuận thực hiện được từ các bản ghi dự báo giả lập này. Đã bỏ ngôn ngữ về hiệu quả giao dịch, nêu rõ nghiên cứu đo sai số dự báo dưới bộ sinh xác định. Đánh giá có thực hiện lệnh là nghiên cứu tiếp theo cần giá, khớp lệnh, phí.” Cách trả lời giải quyết vấn đề bằng sửa phạm vi trung thực.'),B('response-to-review.md and manuscript-v2.md.','response-to-review.md và manuscript-v2.md.'),steps(B('A complete review response','Trả lời phản biện đầy đủ'),[B('R1: confirm shuffled-split defect','R1: xác nhận lỗi chia xáo trộn'),B('P2: chronological replacement','P2: thay bằng chia thời gian'),B('E4–E9: rerun; difference +0.1','E4–E9: chạy lại; chênh lệch +0,1'),B('Figure 2 and conclusion updated','Cập nhật Hình 2 và kết luận')],B('Each node names an artifact that a reviewer can inspect.','Mỗi nút nêu hiện vật người phản biện có thể kiểm tra.')))
]));

modules.push(M(99,B('An independent reproduction package','Gói tái lập độc lập'),B('Reproduction means another clean environment can follow documented steps and obtain the stated outputs within declared tolerances. It is different from proving the scientific claim true. A package needs inputs, versioned code, environment instructions, commands and expected outputs. A tiny synthetic fixture checks plumbing cheaply; it does not replace the full experiment. No paid software or unavailable dataset is required in this week.','Tái lập nghĩa là môi trường sạch khác làm theo hướng dẫn và thu đầu ra đã nêu trong sai số cho phép. Điều đó khác chứng minh kết luận khoa học đúng. Gói cần đầu vào, mã có phiên bản, hướng dẫn môi trường, lệnh và đầu ra mong đợi. Bộ dữ liệu giả lập nhỏ kiểm tra đường chạy với chi phí thấp, không thay thí nghiệm đầy đủ. Tuần này không cần phần mềm trả phí hay bộ dữ liệu không có sẵn.'),[
S(B('Define the reproduction contract','Định nghĩa điều kiện tái lập'),B('A reproduction contract states the command, input, expected output and tolerance. “Run the notebook” is ambiguous if hidden cells or local files are required. Separate exact assertions, such as row count, from floating-point comparisons where a documented tolerance is appropriate.','Điều kiện tái lập nêu lệnh, đầu vào, đầu ra mong đợi và dung sai. “Chạy notebook” mơ hồ nếu cần ô ẩn hoặc tệp chỉ có trên máy tác giả. Tách kiểm tra chính xác như số hàng khỏi so sánh số thực cần dung sai được ghi rõ.'),B('Fixture targets=[1,3], predictions=[2,2]. The contract requires 2 scored rows and MSE=1 within absolute tolerance 10⁻¹². Both squared errors are 1. A result with 1 row and MSE=1 still fails because the count is wrong. Matching the final scalar alone is insufficient.','Mục tiêu thử=[1,3], dự báo=[2,2]. Điều kiện yêu cầu chấm 2 hàng và MSE=1 với dung sai tuyệt đối 10⁻¹². Hai sai số bình phương đều 1. Kết quả có 1 hàng, MSE=1 vẫn trượt vì số hàng sai. Chỉ khớp số cuối chưa đủ.'),[B('Write the fixture and expected result as small JSON files.','Viết dữ liệu thử và kết quả mong đợi thành JSON nhỏ.'),B('Implement row-count and absolute-tolerance assertions.','Viết kiểm tra số hàng và dung sai tuyệt đối.'),B('Solve the exercise and distinguish two failure types.','Giải bài, phân biệt hai loại thất bại.'),B('Write reproduction-contract.md with a single clean-start command.','Viết reproduction-contract.md có một lệnh bắt đầu sạch.')],B('Expected n=3 and MSE=2 within 0.001. A reports n=3,MSE=2.0005; B reports n=2,MSE=2. Which pass?','Mong đợi n=3, MSE=2 trong dung sai 0,001. A báo n=3,MSE=2,0005; B báo n=2,MSE=2. Trường hợp nào đạt?'),B('Both count and numeric tolerance must pass.','Cả số hàng và dung sai số phải đạt.'),B('A passes: count matches and |2.0005−2|=0.0005≤0.001. B fails the count even though its scalar matches exactly. A contract is a conjunction of requirements, not a choice among them.','A đạt: số hàng khớp, |2,0005−2|=0,0005≤0,001. B trượt số hàng dù số cuối khớp tuyệt đối. Điều kiện tái lập là đồng thời các yêu cầu, không chọn một trong số đó.'),B('reproduction-contract.md and two intentionally failing fixtures.','reproduction-contract.md và hai ca thử cố ý sai.'),steps(B('Fixture-to-result contract','Điều kiện từ dữ liệu thử tới kết quả'),[B('Input: y=[1,3], prediction=[2,2]','Đầu vào: y=[1,3], dự báo=[2,2]'),B('Two squared errors: [1,1]','Hai sai số bình phương: [1,1]'),B('Require n=2 AND MSE≈1','Yêu cầu n=2 VÀ MSE≈1')],B('The conjunction catches missing-row errors that a scalar check misses.','Điều kiện đồng thời bắt lỗi thiếu hàng mà kiểm tra số cuối bỏ sót.'))),
S(B('Environment and determinism','Môi trường và tính xác định'),B('A random seed controls a random-number stream only within the specified generator and execution setup. Different library versions or parallel reduction orders may change outputs. Record versions and distinguish deterministic fixture expectations from stochastic experiment summaries. Do not force exact equality across hardware when the method only promises a tolerance.','Seed kiểm soát chuỗi số ngẫu nhiên trong bộ sinh và môi trường đã định. Phiên bản thư viện hoặc thứ tự cộng song song có thể đổi đầu ra. Ghi phiên bản, phân biệt kết quả thử xác định với tóm tắt thí nghiệm ngẫu nhiên. Không ép bằng nhau tuyệt đối giữa phần cứng khi phương pháp chỉ bảo đảm trong dung sai.'),B('Provided manifest A: Python 3.11, NumPy 1.x, generator G1, seed 7. Manifest B: same seed but generator G2. The seed strings match, but identical samples are not promised. For a deterministic checksum test, store the tiny input [1,3] explicitly; for a simulation, record generator/version/seed and summarize all planned runs.','Manifest A: Python 3.11, NumPy 1.x, bộ sinh G1, seed 7. B cùng seed nhưng bộ sinh G2. Chuỗi seed giống nhau không bảo đảm mẫu giống nhau. Với kiểm thử xác định, lưu thẳng đầu vào nhỏ [1,3]; với giả lập, ghi bộ sinh/phiên bản/seed và tổng hợp mọi lần đã định.'),[B('List every field needed to distinguish the two manifests.','Liệt kê trường cần để phân biệt hai manifest.'),B('Create an environment manifest from your actual runtime without inventing versions.','Tạo manifest từ môi trường đang chạy, không bịa phiên bản.'),B('Solve the exercise and define a reasonable tolerance policy.','Giải bài, định nghĩa chính sách dung sai hợp lý.'),B('Document which outputs should be byte-identical and which are numerical comparisons.','Ghi đầu ra nào cần giống từng byte, đầu ra nào so số học.')],B('Two runs return 0.30000000000000004 and 0.3. A contract uses absolute tolerance 10⁻¹². Are they numerically consistent? Does this prove all outputs reproducible?','Hai lần trả 0,30000000000000004 và 0,3. Dung sai tuyệt đối 10⁻¹². Có nhất quán số học không? Có chứng minh mọi đầu ra tái lập không?'),B('Compare the difference with tolerance, then limit the conclusion to this field.','So chênh lệch với dung sai rồi giới hạn kết luận ở trường này.'),B('Their difference is about 5.55×10⁻¹⁷, below 10⁻¹², so this field passes. It does not verify row alignment, other metrics, manifests or the scientific claim. Floating-point agreement is one check within a broader contract.','Chênh lệch khoảng 5,55×10⁻¹⁷ nhỏ hơn 10⁻¹² nên trường này đạt. Không xác minh ghép hàng, thước đo khác, manifest hay kết luận khoa học. Khớp số thực chỉ là một kiểm tra trong điều kiện rộng hơn.'),B('environment.json and a documented equality/tolerance policy.','environment.json và chính sách bằng nhau/dung sai.'),steps(B('Seed is one part of the record','Seed chỉ là một phần bản ghi'),[B('Input or data version','Đầu vào hoặc phiên bản dữ liệu'),B('Generator + library + execution settings','Bộ sinh + thư viện + thiết lập chạy'),B('Seed and planned run IDs','Seed và ID lần chạy đã định'),B('Expected outputs and tolerances','Đầu ra mong đợi và dung sai')],B('All fields matter; a seed alone does not define an experiment.','Mọi trường đều quan trọng; seed đơn lẻ không định nghĩa thí nghiệm.'))),
S(B('Trace a figure back to a command','Truy hình về lệnh tạo'),B('A reader should be able to regenerate a figure from its source data using a named command. Manual edits to numeric labels break this chain. Store presentation choices separately from computed results, and validate that displayed values match the source table. A source hash detects changes but does not prove data quality.','Người đọc cần tái tạo hình từ dữ liệu nguồn bằng lệnh được nêu. Sửa tay nhãn số làm đứt chuỗi. Tách lựa chọn trình bày khỏi kết quả tính, kiểm tra số hiển thị khớp bảng nguồn. Mã băm phát hiện thay đổi nhưng không chứng minh dữ liệu chất lượng.'),B('Provided chain: fixture.json → score.py → results.json containing {baseline:2,model:1.5} → plot.py → figure.svg. Caption says reduction 25%, computed (2−1.5)/2. If results.json changes model to 1.8, rerender both bars and caption; the new reduction is 10%.','Chuỗi cho trước: fixture.json → score.py → results.json chứa {baseline:2,model:1.5} → plot.py → figure.svg. Chú thích giảm 25%, tính (2−1,5)/2. Nếu results.json đổi model thành 1,8, phải dựng lại cả cột lẫn chú thích; mức giảm mới là 10%.'),[B('Write the five-node dependency chain in a manifest.','Viết chuỗi phụ thuộc năm nút vào manifest.'),B('Generate the caption from the same values used for the bars.','Tạo chú thích từ chính số dùng vẽ cột.'),B('Solve the exercise and catch a stale caption automatically.','Giải bài, tự động bắt chú thích lỗi thời.'),B('Add a figure-reproduction command and expected output path to the README.','Thêm lệnh tái tạo hình, đường dẫn đầu ra mong đợi vào README.')],B('Baseline=4, model=3.2 but a manually edited caption says “30% reduction.” Calculate the correct value and name the defect.','Đối chứng=4, mô hình=3,2 nhưng chú thích sửa tay ghi “giảm 30%”. Tính đúng và gọi tên lỗi.'),B('Compute the reduction from the plotted numbers.','Tính mức giảm từ các số thực sự được vẽ.'),B('Reduction=(4−3.2)/4=0.2=20%. The caption is inconsistent with its data source, likely stale or manually altered. Regenerate it from the shared result record and add an assertion; changing the bar height to fit the caption would falsify the result.','Mức giảm=(4−3,2)/4=0,2=20%. Chú thích không nhất quán nguồn, có thể lỗi thời hoặc sửa tay. Tạo lại từ bản ghi chung và thêm kiểm tra; đổi chiều cao cột để khớp chú thích sẽ làm sai kết quả.'),B('figure-manifest.json and a data-driven caption.','figure-manifest.json và chú thích sinh từ dữ liệu.'),bars(B('Values from the original result record','Giá trị bản ghi kết quả gốc'),[B('Baseline','Đối chứng'),B('Model','Mô hình')],[2,1.5],B('Mean loss','Sai số trung bình'),B('Original record: (2−1.5)/2=25% reduction. The hypothetical later 1.8 value is not plotted here.','Bản ghi gốc: (2−1,5)/2=25%. Giá trị 1,8 giả định cập nhật sau không được vẽ ở đây.'))),
S(B('Package only material you can redistribute','Đóng gói đúng quyền phân phối'),B('Publicly readable does not automatically mean redistributable. For this exercise, permissions are supplied as explicit fictional license cards, so no legal interpretation is required. Keep code, data and figures separate because their permissions may differ. If redistribution is forbidden, provide an authorized acquisition instruction and a synthetic fixture rather than bundling the file.','Đọc công khai không tự động có nghĩa được phân phối lại. Trong bài này quyền được cho rõ bằng thẻ giấy phép giả định nên không cần diễn giải pháp luật. Tách mã, dữ liệu, hình vì quyền có thể khác. Nếu cấm phân phối lại, cung cấp hướng dẫn lấy hợp lệ và dữ liệu giả lập thử thay vì đóng gói tệp.'),B('Cards: A permits redistribution with attribution; B permits personal analysis only and forbids redistribution; C is synthetic data you created with no third-party inputs. Package A with its attribution, exclude B and document the restriction, include C as the clean-start fixture. Do not strip A’s notice to make the repository shorter.','Thẻ: A cho phân phối lại kèm ghi nguồn; B chỉ cho phân tích cá nhân, cấm phân phối lại; C là dữ liệu giả lập bạn tự tạo không có đầu vào bên thứ ba. Gói A kèm ghi nguồn, loại B và ghi hạn chế, đưa C làm dữ liệu thử bắt đầu sạch. Không bỏ thông báo của A để kho ngắn hơn.'),[B('Create an asset inventory assigning each file to A, B or C.','Lập danh mục gán mỗi tệp vào A, B hoặc C.'),B('Write a packaging allowlist that includes A and C only.','Viết danh sách cho phép đóng gói chỉ gồm A, C.'),B('Solve the exercise using only the stated permission cards.','Giải bài chỉ dựa quyền được nêu trên thẻ.'),B('Prepare attribution.md and a synthetic-data generation command.','Chuẩn bị attribution.md và lệnh sinh dữ liệu giả lập.')],B('A new card D allows linking but forbids copying. Can you include D’s PDF in the repository? What can the README include?','Thẻ D cho dẫn liên kết nhưng cấm sao chép. Có thể đưa PDF D vào kho không? README có thể gồm gì?'),B('Follow the stated permission, not whether the file is easy to download.','Theo quyền đã nêu, không theo việc tệp dễ tải hay không.'),B('Do not bundle the PDF. The README may include the permitted link and identify D as optional background. The required runnable example must use permitted inputs such as C. This answer follows the fictional card; real assets require checking their actual terms.','Không đóng gói PDF. README có thể dẫn liên kết được phép và ghi D là nền đọc thêm tùy chọn. Ví dụ bắt buộc chạy được phải dùng đầu vào được phép như C. Đáp án theo thẻ giả định; tài sản thật cần kiểm tra điều khoản thật.'),B('asset-inventory.csv, attribution.md and a packaging allowlist.','asset-inventory.csv, attribution.md và danh sách đóng gói cho phép.'),steps(B('Permission-aware package','Gói theo quyền đã cho'),[B('A: include with attribution','A: đưa vào kèm ghi nguồn'),B('B: exclude; document restriction','B: loại; ghi hạn chế'),B('C: include as synthetic fixture','C: đưa vào làm dữ liệu thử giả lập')],B('The branches follow the supplied fictional permission cards.','Các nhánh tuân đúng thẻ quyền giả định đã cho.'))),
S(B('Run a clean-room rehearsal','Diễn tập tái lập từ môi trường sạch'),B('A clean-room rehearsal starts from a fresh copy and follows only the public instructions. It exposes hidden dependencies such as absolute paths, untracked data or notebook state. Log the first failure before fixing it, then repeat from a fresh start. Success means the declared contract passed, not that the model is scientifically correct.','Diễn tập sạch bắt đầu từ bản sao mới và chỉ làm theo hướng dẫn công khai. Nó lộ phụ thuộc ẩn như đường dẫn tuyệt đối, dữ liệu chưa theo dõi, trạng thái notebook. Ghi lỗi đầu tiên trước khi sửa rồi thử lại từ đầu sạch. Thành công nghĩa điều kiện khai báo đạt, không phải mô hình đúng khoa học.'),B('Provided rehearsal log: step 1 installs dependencies; step 2 fails opening /home/author/data.csv; README never creates that file. Repair: use a project-relative input path, add a command generating the supplied synthetic fixture and document it before scoring. Rerun in a new temporary directory to ensure the author’s old file is not masking the issue.','Nhật ký diễn tập: bước 1 cài thư viện; bước 2 lỗi mở /home/author/data.csv; README không tạo tệp đó. Sửa: dùng đường dẫn tương đối trong dự án, thêm lệnh sinh dữ liệu giả lập đã cho, ghi trước bước chấm. Chạy lại trong thư mục tạm mới để tệp cũ của tác giả không che lỗi.'),[B('Write the minimal failing reproduction from the supplied log.','Viết cách tái hiện tối thiểu từ nhật ký đã cho.'),B('Implement project-relative fixture generation and scoring commands.','Viết lệnh sinh dữ liệu, chấm bằng đường dẫn tương đối dự án.'),B('Solve the exercise and test from an empty working directory.','Giải bài, thử từ thư mục làm việc rỗng.'),B('Complete reproduction-report.md listing commands, outputs, failures and fixes.','Hoàn thành reproduction-report.md ghi lệnh, đầu ra, lỗi, cách sửa.')],B('A notebook passes only after cell 8 has been run manually before cell 3. Explain the hidden dependency and give an acceptance test.','Notebook chỉ chạy đúng khi chạy tay ô 8 trước ô 3. Giải thích phụ thuộc ẩn và cho kiểm tra chấp nhận.'),B('A fresh kernel should execute the documented order without prior state.','Kernel mới phải chạy theo thứ tự ghi trong hướng dẫn, không cần trạng thái cũ.'),B('Cell 3 depends on state created later in cell 8, so the visible order is incomplete. Move initialization before its first use or refactor into explicit functions. Acceptance: restart the kernel, run all cells top to bottom and verify the contract without manual intervention. A saved successful output is not a substitute for this test.','Ô 3 phụ thuộc trạng thái tạo muộn ở ô 8 nên thứ tự hiển thị chưa đầy đủ. Đưa khởi tạo trước lần dùng đầu hoặc tách hàm rõ. Chấp nhận: khởi động lại kernel, chạy mọi ô từ trên xuống, kiểm tra điều kiện không can thiệp tay. Đầu ra thành công được lưu sẵn không thay được phép thử này.'),B('reproduction-report.md with a clean-start pass/fail record.','reproduction-report.md có bản ghi đạt/trượt từ đầu sạch.'),steps(B('Rehearsal and repair loop','Vòng diễn tập và sửa'),[B('Fresh copy → follow README only','Bản sao mới → chỉ theo README'),B('Fail: hidden absolute data path','Lỗi: đường dẫn dữ liệu tuyệt đối ẩn'),B('Repair path and add fixture command','Sửa đường dẫn, thêm lệnh tạo dữ liệu thử'),B('Fresh copy again → verify contract','Bản sao mới lần nữa → kiểm tra điều kiện')],B('A second clean start prevents old local files from hiding the repaired dependency.','Bắt đầu sạch lần hai tránh tệp cục bộ cũ che phụ thuộc vừa sửa.')))
]));

writeFileSync(new URL('../data/lessons-94-99.json',import.meta.url),JSON.stringify(modules,null,2)+'\n');
